@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/variables';
@use 'outline';
@use 'reset';

@mixin navigation-anchor(
    $color: colors.$color-purewhite,
    $background: colors.$color-gray10,
    $hover-color: colors.$color-purewhite,
    $hover-background: colors.$color-gray8,
    $outline: colors.$color-purewhite
) {
    @include reset.anchor-reset();

    background-color: $background;
    color: $color;
    transition: background-color ease-out variables.$transition-duration;

    &:focus,
    &:active {
        color: $color;

        span {
            outline-color: $outline;
            outline-offset: variables.$border-width-thick;
            outline-style: variables.$border-style-solid;
            outline-width: variables.$border-width-default;
        }
    }

    &:hover {
        @include include-media.media('hover') {
            background-color: $hover-background;
            color: $hover-color;
        }
    }
}

@mixin navigation-button(
    $color: colors.$color-purewhite,
    $background: colors.$color-gray10,
    $hover: colors.$color-gray8,
    $outline: colors.$color-purewhite
) {
    @include reset.anchor-reset();
    @include outline.anchor-default-outline($outline);

    background-color: $background;
    color: $color;
    transition: background-color ease-out variables.$transition-duration;

    &:focus {
        span {
            color: $color;
        }
    }

    &:hover {
        @include include-media.media('hover') {
            background-color: $hover;
            color: $color;
        }
    }
}

@mixin navigation-button-transition-helper($bg-border-color) {
    background: $bg-border-color;
    border: variables.$border-width-thicker variables.$border-style-solid
        $bg-border-color;
    border-bottom: variables.$border-width-thicker variables.$border-style-solid
        $bg-border-color;
    width: measurements.$measure--small4;

    &:focus,
    &:active,
    &:hover {
        outline-offset: -(variables.$border-width-hairline);
        border-bottom: variables.$border-width-thicker
            variables.$border-style-solid $bg-border-color;
    }
}
