@use 'sass:math';
@use '../../../abstracts/measurements';
@use '../../../abstracts/palette';
@use '../../../abstracts/variables';
@use '../../../base/page';
@use '../../../base/typography';
@use '../../../layout/grid';
@use '../../../abstracts/colors';

@use '../../../abstracts/media' as include-media;

main {
    .home__research {
        // Generic
        padding-top: measurements.$measure--half;
        background: colors.$color-purewhite;

        .wrap--research__content {
            background: colors.$color-gray4;
            padding-bottom: measurements.$measure--small4;
        }

        .wrap--research__links {
            h3 {
                color: colors.$color-gray10;
            }
        }

        @include include-media.media('>=large') {
            .wrap--research__content {
                padding-bottom: measurements.$measure--medium11;
            }
        }

        .research__content {
            color: colors.$color-purewhite;
        }

        .research__heading,
        .research__intro,
        .research__links {
            @include typography.heading-font-features();
            @include typography.font-family('heading');
        }

        .research__heading,
        .research__intro {
            grid-column: 1/-1;
        }

        .research__intro {
            margin-bottom: measurements.$measure--medium7;
            @include typography.betatype();
        }

        .wrap--research__media {
            margin-top: -(measurements.$measure--small5);
            position: relative;
            height: 100%;
            background: colors.$color-gray4;

            .youtube-video__wrapper {
                padding-bottom: 56.25%;
                position: relative;
                iframe {
                    height: 100%;
                    margin: 0;
                    position: absolute;
                    width: 100%;
                }
            }

            .youtube-video {
                margin-top: 0;
            }

            .media__container {
                position: absolute;
                width: 100%;
                height: 100%;

                &.in {
                    visibility: visible;
                    opacity: 1;
                    transition: visibility
                            math.div(variables.$transition-duration--long, 2),
                        opacity
                            math.div(variables.$transition-duration--long, 2)
                            linear;
                }

                &.out {
                    visibility: hidden;
                    opacity: 0;
                    transition: visibility
                            math.div(variables.$transition-duration--long, 2),
                        opacity
                            math.div(variables.$transition-duration--long, 2)
                            linear;
                }
            }
        }

        .media__container__img {
            object-fit: cover;
            width: 100%;
        }

        .research__links {
            list-style-type: none;
            margin: 0;
        }

        .linked-heading {
            display: block;
            &:active,
            &:focus {
                outline: variables.$border-width-default
                    variables.$border-style-solid colors.$color-gray11;
            }

            &:focus {
                transition: none;
                background-image: none;
                background-size: 0;

                .linked-heading__text {
                    &:before {
                        opacity: 1;
                        width: 100%;
                    }
                }

                .linked-heading__icons {
                    span:nth-child(1) {
                        display: none;
                        visibility: hidden;
                        opacity: 0;
                        animation: slide-right-out 600ms;
                    }

                    span:nth-child(2) {
                        display: inherit;
                        visibility: visible;
                        opacity: 1;
                        animation: slide-left-in 600ms;
                    }
                }
            }
        }

        .linked-heading__text {
            color: colors.$color-gray10;
            border-bottom-color: colors.$color-gray4;
        }

        .linked-heading__icons {
            background: transparent;
            color: palette.$color-brand-primary;
            width: measurements.$measure--small2;
            height: measurements.$measure--small2;
            position: absolute;
            right: 0;
            transform: translateY(-50%);
            top: 50%;

            span {
                &:nth-child(1),
                &:nth-child(2) {
                    font-size: typography.$font-size--icon;
                }
            }
        }

        @include include-media.media('<tablet') {
            .research__content {
                flex-direction: column;
            }

            .wrap--research__media {
                margin-bottom: -(measurements.$measure--basic);
                margin-left: -(measurements.$measure--basic);
                margin-right: measurements.$measure--small4;

                .media__container {
                    &.in,
                    &.out {
                        position: relative;

                        &:first-of-type {
                            opacity: 1;
                            visibility: visible;
                        }

                        &:not(:first-of-type) {
                            display: none;
                        }
                    }
                }
            }
        }

        @include include-media.media('<small') {
            .research__content {
                @include page.default-margin();
                display: flex;
                gap: measurements.$measure--basic;
                > * {
                    flex: 1;
                }
            }

            .wrap--research__intro {
                @include page.default-margin();
            }

            .media__container__img {
                height: 100%;
            }
        }

        @include include-media.media('>=tablet') {
            .wrap--research__media {
                grid-column: 1/11;
                height: auto;
            }

            .research__content {
                @include grid.content-grid;
            }

            .wrap--research__links {
                grid-column: 12/-2;
                margin-top: measurements.$measure--small2;
            }
        }

        @include include-media.media('>=tablet', '<small') {
            .wrap--research__content {
                padding-bottom: measurements.$measure--medium3;
            }
        }

        @include include-media.media('>=small') {
            .wrap--research__intro,
            .research__content {
                @include page.standard-box();
            }

            .media__container__img {
                width: 100%;
            }

            .wrap--research__content {
                padding-bottom: measurements.$measure--large4;
            }
        }
    }
}
