@use 'home-vi-sections/banner';
@use 'home-vi-sections/banner-promo';
@use 'home-vi-sections/banner-hero';
@use 'home-vi-sections/pathway';
@use 'home-vi-sections/social-image-grid';
@use 'home-vi-sections/news-events';
@use 'home-vi-sections/promo';
@use 'home-vi-sections/research';
@use '../../patterns/campuses-cards/campuses-cards';
@use '../../abstracts/measurements';
@use '../../base/typography';

.home-new-vi {
    // body class override, development only

    .breadcrumbs {
        display: none;
    }

    .navigation--secondary {
        display: none;
    }

    .triangle__block {
        width: measurements.$measure--huge5;
    }

    .triangle__block--left {
        margin-bottom: -(measurements.$measure--huge3);
    }

    .triangle__block--right {
        right: 0;
        position: absolute;
        transform: rotate(180deg);
        margin-top: -(measurements.$measure--huge5);
    }
}

.home-new-vi {
    main {
        margin: 0;
        padding: 0;
        p {
            max-width: typography.$max-line-length;
        }

        .outline-cta--rounded-edges {
            margin-bottom: 0;
        }
    }
}
