@use 'linked-heading';
@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/palette';
@use '../../anchors/anchors';
@use '../../anchors/discreet';
@use '../../anchors/inline';
@use '../../anchors/mixins-cta';
@use '../../anchors/underline-transition';

.anchor-inline--gray {
    @include inline.anchor-inline(
        colors.$color-gray12,
        colors.$color-gray12,
        colors.$color-nearblack,
        palette.$color-outline--dark
    );
}

.anchor-inline--gray4 {
    @include inline.anchor-inline(
        colors.$color-gray4,
        colors.$color-gray4,
        colors.$color-nearblack,
        palette.$color-outline--dark
    );
}

.anchor-inline--dark {
    @include inline.anchor-inline(
        colors.$color-gray11,
        colors.$color-gray11,
        colors.$color-purewhite,
        palette.$color-outline
    );
}

.anchor-discreet {
    @include discreet.anchor-discreet;
}

.anchor-inline--notvisited {
    @include inline.anchor-inline(
        palette.$color-inline-link,
        palette.$color-inline-link,
        palette.$color-text--dark,
        palette.$color-outline
    );
}

.anchor-cta-like {
    @include anchors.cta-like-anchors;
}

.anchor-underline-transition {
    @include underline-transition.underline-transition;
}

ul.cta-like-anchor-block {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    max-width: none;
    margin: measurements.$measure--basic 0 0;

    li.cta-like-anchor {
        width: calc(
            1 / 2 * 100% - (1 - 1 / 2) * #{measurements.$measure--half}
        );
        list-style-type: none;

        @include include-media.media('<tablet') {
            width: 100%;
        }

        a {
            @include mixins-cta.cta-outlined-light-bg(
                colors.$color-gray11,
                colors.$color-gray6
            );
            width: 100%;
            height: 100%;
        }
    }
}

ul.cta-like-anchor-inline {
    display: flex;
    max-width: none;
    margin: measurements.$measure--basic 0 0;

    li.cta-like-anchor {
        list-style-type: none;
        margin-right: measurements.$measure--basic;
        &:last-child {
            margin-right: 0;
        }

        @include include-media.media('<tablet') {
            width: 100%;
        }

        a {
            @include anchors.cta-like-anchors;
            span {
                margin: 0;
            }
        }

        .cta-like-anchor__text {
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            flex-wrap: wrap;

            @include include-media.media('>tablet') {
                flex-wrap: nowrap;
            }
        }
    }
}
