@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../anchors/cta--basic';
@use '../../anchors/cta--border';
@use '../../anchors/img';
@use '../../anchors/inline';
@use '../../anchors/outline';
@use '../../anchors/reset';
@use '../../base/content';
@use '../../base/page';
@use '../../base/typography';
@use '../../layout/grid';

.global-header__search {
    @include include-media.media('<small') {
        margin: measurements.$measure--half;
    }

    @include include-media.media('>=small') {
        width: 100%;
    }

    .global-header__search__wrapper {
        @include content.content-style();

        align-items: center;
        display: inline-flex;
        flex-direction: row;
        flex-wrap: nowrap;
        justify-content: center;
        margin-top: 0;

        @include include-media.media('<small') {
            @include typography.betatype();

            flex-direction: column-reverse;
        }
    }

    > a,
    .global-header__search__button {
        transition: transform 0.3s ease;

        @include include-media.media('<small') {
            @include cta--border.cta--border--subelement(
                transparent,
                colors.$color-nearblack,
                colors.$color-gray6,
                colors.$color-nearblack,
                colors.$color-purewhite,
                colors.$color-nearblack,
                colors.$color-purewhite,
                square
            );

            display: flex;
            height: measurements.$measure--medium7;
            padding-bottom: 0;
            padding-left: 0;
            padding-right: 0;
            padding-top: 0;
            width: measurements.$measure--medium7;
        }

        &:active,
        &:focus {
            @include outline.outline-properties(colors.$color-nearblack);
        }

        .global-header__search__text {
            @include typography.smalltype();

            font-weight: variables.$font-weight-book;
        }

        @include include-media.media('<small') {
            justify-content: center;

            .global-header__search__icon {
                @include typography.epsilontype();
            }
        }

        @include include-media.media('>=small') {
            display: flex;
            height: 100%;

            &:hover {
                @include include-media.media('hover') {
                    transform: scale(1.2);
                }
            }

            .global-header__search__icon {
                @include typography.epsilontype();
                color: colors.$color-red50;
            }

            .global-header__search__text {
                display: none;
            }
        }

        @include include-media.media('>=desktop') {
            @include content.h5style();
            margin-top: 0;
        }

        align-items: center;
        flex-direction: row;
        flex-wrap: nowrap;
    }
}

.js .global-header__search {
    .global-header__search__button[aria-expanded='false'] {
        & + .global-header__search__modal {
            transform: translateY(100%);
            opacity: 0;
            pointer-events: none;
        }
    }

    .global-header__search__button[aria-expanded='true'] {
        & + .global-header__search__modal {
            transform: translateY(0);
            opacity: 1;
            pointer-events: auto;
        }
        @include include-media.media('<small') {
            @include cta--basic.cta--basic--subelement(
                colors.$color-purewhite,
                colors.$color-nearblack,
                colors.$color-purewhite,
                colors.$color-gray10,
                colors.$color-purewhite,
                square
            );

            border: 0;
            margin-right: measurements.$measure--half;
            margin-top: measurements.$measure--half;
            padding-left: 0;
            padding-right: 0;
            padding-top: 0;
        }

        &:active,
        &:focus {
            @include outline.outline-properties(colors.$color-purewhite);
        }

        .global-header__search__icon {
            color: colors.$color-purewhite;
        }
    }

    .global-header__search__button {
        & + .global-header__search__modal {
            @include mixins.box-shadow();

            background: colors.$color-nearblack;
            color: colors.$color-purewhite;
            display: block;
            left: 0;
            min-height: 100vh;
            position: fixed;
            right: 0;
            top: 0;
            z-index: functions.z-index('navigation');
            width: 100vw;
            // transform: translate(-50%, 0%);
            // left: 50%;

            .global-header__search__modal__header {
                @include include-media.media('<small') {
                    align-items: flex-start;
                    display: flex;
                    flex-direction: row;
                    flex-wrap: nowrap;
                    justify-content: space-between;
                }

                @include include-media.media('>=small') {
                    @include grid.standard-grid();
                    @include page.standard-box();

                    grid-template-rows: repeat(3, 1fr);
                }

                @include include-media.media('>=desktop') {
                    grid-row-gap: measurements.$measure--basic;
                    grid-template-rows: repeat(2, 1fr);
                }

                .global-header__search__button {
                    @include include-media.media('>=small') {
                        grid-column: 24 / span 1;
                        margin-top: measurements.$measure--basic;
                    }
                }
            }

            .global-header__search__modal__body {
                @include page.default-padding();

                padding-bottom: measurements.$measure--small4;

                @include include-media.media('>=small') {
                    @include grid.standard-grid();
                    @include page.standard-box();
                }

                h2 {
                    @include content.h2style();

                    margin-top: measurements.$measure--small4;
                    text-align: center;
                    grid-column: span 24;
                }

                h3 {
                    @include content.h3style();

                    margin-top: measurements.$measure--small2;
                }

                form {
                    grid-column: 4 / span 18;
                    margin-top: variables.$content-element-margin;
                }
            }

            .global-header__search__modal__body__results {
                grid-column: 4 / span 18;

                @include include-media.media('>=small') {
                    @include grid.content-grid();

                    .search--inline__suggestions,
                    .search--inline__results__updating--suggestions {
                        grid-column: 1 / span 6;

                        &:only-child {
                            grid-column: 7 / span 6;
                        }
                    }

                    .search--inline__topresults,
                    .search--inline__results__updating--topresults {
                        grid-column: 7 / span 12;

                        &:only-child {
                            grid-column: 4 / span 12;
                        }
                    }
                }

                .search--inline__topresults,
                .search--inline__results__updating--topresults {
                    ul {
                        list-style: none;
                        margin-top: variables.$content-element-margin;
                    }

                    .card--search {
                        padding-bottom: measurements.$measure--basic;

                        a {
                            @include reset.anchor-reset();

                            background-color: transparent;
                            color: colors.$color-purewhite;

                            &:hover {
                                @include include-media.media('hover') {
                                    color: colors.$color-purewhite;
                                }
                            }

                            &:active,
                            &:focus {
                                @include outline.outline-properties(
                                    colors.$color-purewhite
                                );

                                color: colors.$color-purewhite;
                            }

                            .card__heading {
                                @include content.h4style();

                                background-image: linear-gradient(
                                    120deg,
                                    colors.$color-purewhite 0%,
                                    colors.$color-purewhite 100%
                                );
                                background-position: 0 100%;
                                background-repeat: no-repeat;
                                background-size: 100% 0;
                                border-bottom-color: colors.$color-purewhite;
                                border-bottom-style: variables.$border-style-solid;
                                border-bottom-width: variables.$border-width-default;
                                display: inline;
                                max-width: typography.$max-line-length;
                                transition: background-size
                                    variables.$transition-duration
                                    variables.$transition-function;

                                @include include-media.media('reducemotion') {
                                    transition: none;
                                }
                            }

                            &:hover {
                                @include include-media.media('hover') {
                                    .card__thumbnail {
                                        transform: scale(1.02);
                                    }

                                    .card__heading {
                                        background-size: 100% 100%;
                                        background-image: linear-gradient(
                                            120deg,
                                            colors.$color-purewhite 0%,
                                            colors.$color-purewhite 100%
                                        );
                                        color: colors.$color-nearblack;
                                    }
                                }
                            }
                        }

                        .card__label {
                            @include typography.smalltype();

                            color: colors.$color-gray4;
                            font-style: italic;
                        }

                        .card__details {
                            display: flex;
                            flex-wrap: nowrap;

                            @include include-media.media('<small') {
                                flex-direction: column;
                            }

                            @include include-media.media('>=small') {
                                flex-direction: row;
                            }
                        }

                        .card__thumbnail + .card__details__text {
                            @include include-media.media('<small') {
                                padding-left: 0;
                                padding-top: measurements.$measure--basic;
                            }

                            @include include-media.media('>=small') {
                                padding-left: measurements.$measure--basic;
                                padding-top: 0;
                            }
                        }

                        .card__details__text {
                            width: 100%;
                        }

                        .card__description {
                            @include content.content-style();

                            margin-top: variables.$content-element-margin;
                            max-width: typography.$max-line-length;
                        }

                        .card__url {
                            @include typography.smalltype();

                            margin-top: measurements.$measure--basic;
                            max-width: unset;
                            color: colors.$color-gray1;
                            word-break: break-word;
                        }

                        .card__thumbnail {
                            align-self: flex-start;
                            flex-shrink: 0;
                            height: auto;
                            transition: transform variables.$transition-duration
                                ease-in-out;
                            width: measurements.$measure--huge5;

                            @include include-media.media('reducemotion') {
                                transition: none;
                            }
                        }

                        & + .card--search {
                            border-top: variables.$border-width-hairline
                                variables.$border-style-solid
                                colors.$color-gray4;
                            padding-top: measurements.$measure--basic;
                        }
                    }
                }
            }

            .header-logo {
                @include include-media.media('<small') {
                    align-self: center;
                    justify-content: flex-start;
                    padding-bottom: measurements.$measure--half;
                    padding-left: measurements.$measure--half;
                    padding-right: measurements.$measure--half;
                    padding-top: measurements.$measure--half;
                    width: measurements.$measure--huge5;
                }

                @include include-media.media('>=small') {
                    grid-column-end: span 3;
                    grid-column-start: 1;
                    grid-row-end: span 2;
                    grid-row-start: 1;
                }

                a {
                    @include img.anchor-img();

                    display: inline-block;
                    width: 100%;

                    @include include-media.media('<small') {
                        height: measurements.$measure--medium7;
                    }

                    @include include-media.media('>=small') {
                        margin-bottom: measurements.$measure--small2;
                        margin-top: measurements.$measure--small2;
                    }

                    &:active,
                    &:focus {
                        outline-color: colors.$color-purewhite;
                    }

                    .logo {
                        width: 100%;

                        @include include-media.media('<small') {
                            height: 100%;
                        }
                    }
                }
            }
        }
    }

    .veil--search {
        @include mixins.veil();

        &[data-on='true'] {
            position: fixed;
        }
    }

    .search--inline__query__icon--wrapper {
        background-color: colors.$color-purewhite;
        padding-bottom: measurements.$measure--half;
        padding-left: measurements.$measure--half;
        padding-right: measurements.$measure--basic;
        padding-top: #{measurements.$measure--quarter +
            variables.$border-width-hairline};

        @include include-media.media('<tablet') {
            display: none;
        }
    }

    .search--inline__query {
        > div {
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;

            button {
                @include cta--basic.cta--basic--subelement(
                    $color: colors.$color-purewhite,
                    $background: colors.$color-red50,
                    $hover-color: colors.$color-purewhite,
                    $hover-background: colors.$color-red70,
                    $outline: colors.$color-purewhite,
                    $corners: square,
                    $class: 'search--inline__query__submit__content'
                );

                @include include-media.media('<small') {
                    margin-left: measurements.$measure--basic;

                    .search--inline__query__submit__text {
                        @include mixins.sr-only();
                    }
                }

                @include include-media.media('>=small') {
                    margin-left: measurements.$measure--small2;

                    .search--inline__query__submit__icon {
                        display: none;
                    }
                }
            }
        }
    }

    .search--inline__icon {
        background-color: colors.$color-purewhite;
        color: colors.$color-gray7;
        font-weight: variables.$font-weight-text;
        margin-bottom: measurements.$measure--half;
        margin-top: measurements.$measure--threequarters;
    }

    .search--inline__query__input {
        @include typography.font-family('default');
        @include typography.body-font-features();
        @include typography.alphatype();

        @include include-media.media('>=tablet') {
            @include typography.gammatype();
        }

        background-color: colors.$color-purewhite;
        display: flex;
        flex-grow: 1;
        font-weight: variables.$font-weight-text;
        padding: 0;
        position: relative;

        &:focus-within {
            @include outline.outline-properties(colors.$color-purewhite);
        }

        input {
            caret-color: currentColor;
            @include typography.font-family('default');
            @include typography.body-font-features();
            @include typography.gammatype();

            border: variables.$border-width-hairline solid transparent;
            font-style: normal;
            height: 100%;
            min-width: 0; // Constrains width in Firefox
            padding-bottom: measurements.$measure--half;
            padding-left: measurements.$measure--half;
            padding-right: measurements.$measure--medium5;
            padding-top: measurements.$measure--half;
            width: 100%;

            &:focus {
                color: colors.$color-gray10;
                font-style: normal;
                font-weight: variables.$font-weight-medium;
                outline: 0;
            }

            &::placeholder {
                font-style: italic;
            }

            &:placeholder-shown {
                color: colors.$color-gray7;
            }
        }

        .search--inline__clear {
            @include typography.epsilontype();

            align-items: center;
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;
            height: measurements.$measure--small5;
            justify-content: center;
            position: absolute;
            right: measurements.$measure--half;
            top: measurements.$measure--quarter;
            width: measurements.$measure--small5;
            background-color: initial;
            padding: 0;

            &:focus {
                @include outline.outline-properties();

                outline-offset: -#{variables.$border-width-thicker};
            }

            .search--inline__clear__text {
                @include mixins.sr-only();
            }

            .icon {
                /*
                // temp overide with xmark-temp-styling below

                --fa-primary-color: #{colors.$color-gray7};
                --fa-primary-opacity: 1;
                --fa-secondary-color: #{colors.$color-gray1};
                --fa-secondary-opacity: 1;
                */
                letter-spacing: 0;
                line-height: 1;
                @include content.xmark-temp-styling;
            }

            &:hover {
                background-color: transparent;

                .icon {
                    /*
                    // temp overide with xmark-temp-styling below

                    --fa-primary-color: #{colors.$color-gray1};
                    --fa-secondary-color: #{colors.$color-gray7};
                    */
                    @include content.xmark-temp-styling-hover;
                }
            }
        }
    }

    .search--inline__results__updating {
        @include typography.gammatype();

        margin-bottom: variables.$heading-margin;
        margin-top: variables.$heading-margin;

        .icon {
            color: colors.$color-purewhite;
        }
    }

    .search--inline__suggestions {
        ul {
            list-style: none;
            margin-left: 0;
            max-width: typography.$max-line-length;
        }

        li {
            @include content.content-style();
            @include typography.betatype();

            margin-top: variables.$content-element-margin;
        }

        a {
            @include inline.anchor-inline(
                $color: colors.$color-purewhite,
                $visited: colors.$color-purewhite,
                $hover: colors.$color-nearblack,
                $outline: colors.$color-purewhite
            );

            font-weight: variables.$font-weight-light;

            .search--inline__suggestion {
                font-weight: variables.$font-weight-medium;
            }
        }
    }
}
