@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../base/typography';

.card--casestudy {
    &:not(.card--casestudy--alternative) {
        .card__details {
            display: flex;
            flex-wrap: nowrap;

            @include include-media.media('<tablet') {
                flex-direction: column;
            }

            @include include-media.media('>=tablet') {
                flex-direction: row;
            }
        }

        .card__thumbnail + .card__details__text {
            @include include-media.media('<=mobile') {
                padding-left: 0;
                padding-right: 0;
            }

            @include include-media.media('>=small') {
                padding-top: 0;
            }
        }

        .card__details__text {
            padding-top: measurements.$measure--half;
        }

        .card__thumbnail {
            overflow: hidden;

            @include include-media.media('<small') {
                padding-left: measurements.$measure--basic;
            }

            @include include-media.media('<between') {
                height: measurements.$measure--huge1;
                width: measurements.$measure--huge1;
                padding-left: measurements.$measure--basic;
                padding-top: measurements.$measure--basic;
            }

            @include include-media.media('>=between') {
                height: measurements.$measure--huge3;
                width: measurements.$measure--huge3;
            }

            picture,
            img {
                height: 100%;
                max-width: unset;
                width: auto;
            }
        }

        .card__description {
            margin-top: 0;
        }
    }

    &.card--casestudy--alternative {
        padding: measurements.$measure--half;

        .card__anchor {
            display: flex;
            flex-direction: column;
            flex-wrap: nowrap;

            @include include-media.media('>between') {
                flex-direction: row;
            }

            &:after {
                display: none;
            }

            &,
            &:focus,
            &:active,
            &:visited {
                border: none;
            }

            &:hover {
                @include include-media.media('hover') {
                    background-color: transparent;
                    border: none;

                    .card__details__text {
                        background-color: colors.$color-red80;
                    }
                }
            }

            @include include-media.media('<=between') {
                background-color: transparent;
            }

            .wrapper--card__thumbnail {
                align-self: center;
                overflow: hidden;

                @include include-media.media('>between') {
                    width: 45%;
                }
            }

            .card__thumbnail {
                @include include-media.media('<=between') {
                    max-height: 15rem;
                }

                @include include-media.media('>between') {
                    margin-bottom: measurements.$measure--small2;
                    margin-top: measurements.$measure--small2;
                }

                img {
                    display: flex;

                    @include include-media.media('<=between') {
                        height: auto;
                        width: 100%;
                    }
                }
            }

            .card__details__text {
                @include mixins.box-shadow();

                background-color: colors.$color-red70;
                color: colors.$color-purewhite;
                transition: background-color variables.$transition-duration
                    ease-in;

                @include include-media.media('>between') {
                    width: 55%;
                }

                @include include-media.media('reducemotion') {
                    transition: none;
                }

                .card__type {
                    @include typography.extrasmalltype();

                    color: colors.$color-gray2;
                    font-style: italic;
                    margin-bottom: measurements.$measure--basic;
                }
            }
        }
    }
}
