@use 'sass:color';
@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/mixins';
@use '../abstracts/palette';
@use '../abstracts/variables';
@use '../fontawesome-7/functions';
@use 'outline';

////
/// CTA mixin
/// @group abstracts
////
@mixin cta-reset-properties() {
    background: initial;
    border-radius: measurements.$measure--quarter;
    border: none;
    color: initial;
    display: inline-flex;
    font-weight: variables.$font-weight-medium;
    padding: measurements.$measure--half measurements.$measure--small2;
    position: relative;

    &:disabled {
        cursor: default;
    }
}

@mixin cta-reset-icon-properties($icon: '\f061') {
    content: functions.fa-content($icon);
    font-family: 'Font Awesome 7 Pro';
    font-style: normal;
    font-weight: normal;
    opacity: 0;
    position: absolute;
    right: measurements.$measure--small2;
    text-decoration: inherit;
    transform: translateX(-(measurements.$measure--threequarters));
    transition: background-color variables.$transition-duration--long,
        transform variables.$transition-duration--long;
}

@mixin cta-reset($icon: '\f061') {
    @include cta-reset-properties();

    @include include-media.media('reducemotion') {
        transition: none;
    }

    @include include-media.media('<=mobile') {
        display: flex;
        justify-content: center;
        text-align: center;
    }

    transition: background-color variables.$transition-duration--long,
        transform variables.$transition-duration--long;

    span {
        transition: transform variables.$transition-duration--long;
    }

    &:after {
        @include cta-reset-icon-properties($icon);

        @include include-media.media('reducemotion') {
            transition: none;
        }
    }

    &:focus,
    &:active {
        background-color: transparent;
        border: variables.$border-width-default variables.$border-style-solid
            colors.$color-red50;
        color: colors.$color-purewhite;

        span {
            transform: translateX(-(measurements.$measure--threequarters));
        }

        &:after {
            opacity: 1;
            transform: translateX(measurements.$measure--threequarters);
        }
    }

    &:hover {
        @include include-media.media('hover') {
            background-color: transparent;
            border: variables.$border-width-default
                variables.$border-style-solid colors.$color-red50;
            color: colors.$color-purewhite;

            span {
                transform: translateX(-(measurements.$measure--threequarters));
            }

            &:after {
                opacity: 1;
                transform: translateX(measurements.$measure--threequarters);
            }
        }
    }

    &:disabled {
        opacity: 0.7;

        span {
            transform: none;
        }

        &:after {
            opacity: 0;
            transform: none;
        }
    }
}

/**
 *
 * Call to action Primary style on a dark background
 * To use @include cta-primary-dark-bg();
 * this will style the CTA to default primary colours
 *
 * to modify the colours pass in the background colour and colour as parameters
 * e.g @include cta-primary-dark-bg(yellow, green);
 *
 *
 */

@mixin cta-primary-icon-dark-bg(
    $bgColor: palette.$color-brand-primary,
    $color: palette.$color-bg,
    $icon: '\f061'
) {
    @include cta-reset($icon);
    border: variables.$border-width-default variables.$border-style-solid
        $bgColor;
    background: $bgColor;
    color: $color;

    &:visited {
        color: $color;
        border-color: $bgColor;
    }

    &:focus {
        background: $bgColor;
        color: $color;
    }

    &:active,
    &:focus {
        @include outline.anchor-default-outline(palette.$color-outline--dark);
        border-color: $bgColor;
    }

    &:hover,
    &:active {
        @include include-media.media('hover') {
            border-color: $bgColor;
            background-image: none;
            background: transparent;
        }
    }

    &:disabled {
        $color: palette.$color-bg;
        background: $bgColor;
        border: variables.$border-width-default variables.$border-style-solid
            $bgColor;
    }
}

@mixin cta-primary-dark-bg(
    $bgColor: palette.$color-brand-primary,
    $color: palette.$color-bg
) {
    @include cta-primary-icon-dark-bg();

    border-color: $bgColor;
    background: $bgColor;
    color: $color;

    span {
        transition: none;
    }

    &:visited {
        color: $color;
        border-color: $bgColor;
    }

    &:after {
        content: '';
    }

    &:focus {
        border-color: $bgColor;
        background: $bgColor;
        color: $color;
    }

    &:hover {
        @include include-media.media('hover') {
            background: transparent;
            color: $bgColor;
            border-color: $bgColor;
        }
    }

    &:active {
        background: transparent;
        border-color: $bgColor;
        color: $bgColor;
    }

    &:active,
    &:focus,
    &:hover {
        span {
            transform: none;
        }
    }

    &:disabled {
        border-color: $bgColor;
        background: $bgColor;
        color: $color;
    }
}

/**
 *
 * Call to action style for a light background
 * Primary colors will be used if no parameters is pass as args
 * e.g @include cta-primary-light-bg();
 *
 * to modify the colours used pass in a backgound or colour arg
 * e.g @include cta-primary-light-bg(yellow, green);
 *
 */

@mixin cta-primary-icon-light-bg(
    $lgbgColor: palette.$color-brand-primary,
    $lgcolor: colors.$color-purewhite
) {
    @include cta-reset();
    @include mixins.box-shadow();
    background: $lgbgColor;
    border: variables.$border-width-default variables.$border-style-solid
        $lgbgColor;
    color: $lgcolor;

    &:visited {
        border-color: $lgbgColor;
        color: $lgcolor;
    }

    &:focus {
        @include outline.anchor-default-outline(palette.$color-outline);
        background: $lgbgColor;
        border-color: $lgbgColor;
        color: $lgcolor;
    }

    &:hover {
        @include include-media.media('hover') {
            background: $lgcolor;
            border-color: $lgbgColor;
            color: $lgbgColor;
        }
    }

    &:active {
        @include outline.anchor-default-outline(palette.$color-outline);
        border-color: $lgbgColor;
        box-shadow: none;
        color: $lgbgColor;
        background: transparent;
    }

    &:disabled {
        color: $lgcolor;
        background: $lgbgColor;
        border: variables.$border-width-default variables.$border-style-solid
            $lgbgColor;
    }
}

@mixin cta-primary-light-bg(
    $lgbgColor: palette.$color-brand-primary,
    $lgcolor: colors.$color-purewhite
) {
    @include cta-primary-icon-light-bg();
    border-color: $lgbgColor;
