    color: $lgcolor;

    span {
        transition: none;
    }

    &:visited {
        border-color: $lgbgColor;
        color: $lgcolor;
    }

    &:after {
        content: '';
    }

    &:focus,
    &:active {
        color: $lgbgColor;
    }

    &:focus {
        border-color: $lgbgColor;
        background: $lgbgColor;
        color: $lgcolor;
    }

    &:hover {
        @include include-media.media('hover') {
            background: transparent;
            border-color: $lgbgColor;
            color: $lgbgColor;
        }
    }

    &:active {
        color: $lgbgColor;
        border-color: $lgbgColor;
        background: transparent;
    }

    &:active,
    &:focus,
    &:hover {
        span {
            transform: none;
        }
    }

    &:disabled {
        border-color: $lgbgColor;
        background: $lgbgColor;
        color: $lgcolor;
    }
}

