/**
 *
 * CTA on a light background
 * to use with default colours
 * e.g @include cta-basic-light-bg();
 *
 * colours can be modify by passing arg to the mixin
 * e.g @include cta-basic-light-bg(yellow, green);
 * this will change the background to yellow and color to green
 *
 */

@mixin cta-basic-light-bg(
    $bg-color: palette.$color-brand-primary,
    $color: colors.$color-purewhite
) {
    @include cta-primary-icon-light-bg();
    background-color: $bg-color;
    border-color: $bg-color;
    color: $color;

    span {
        transition: none;
    }

    &:visited {
        border-color: $bg-color;
        color: $color;
    }

    &:after {
        content: '';
    }

    &:focus,
    &:active {
        background-color: $bg-color;
        border-color: $bg-color;
        color: $color;
    }

    &:hover {
        @include include-media.media('hover') {
            background-color: color.adjust($bg-color, $lightness: -10%);
            border-color: color.adjust($bg-color, $lightness: -10%);
            color: $color;
        }
    }

    &:active {
        background-color: color.adjust($bg-color, $lightness: -10%);
        border-color: color.adjust($bg-color, $lightness: -10%);
    }

    &:disabled {
        color: $color;
        background: $bg-color;
        border-color: $bg-color;
    }

    &:active,
    &:focus,
    &:hover {
        span {
            transform: none;
        }
    }
}

/**
 *
 * CTA on a dark background
 * To used the default colour
 * e.g @include cta-basic-dark-bg();
 *
 * to modify the colour used you can pass in arg to the mixin
 * e.g @include cta-basic-dark-bg(yellow, blue);
 * this will modify the background and color attributes
 *
 */

@mixin cta-basic-dark-bg(
    $bg-color: palette.$color-brand-primary,
    $color: colors.$color-purewhite
) {
    @include cta-basic-light-bg();
    background-color: $bg-color;
    border-color: $bg-color;
    color: $color;

    &:visited {
        border-color: $bg-color;
        color: $color;
    }

    &:after {
        content: '';
    }

    &:focus,
    &:active {
        background-color: $bg-color;
        border-color: $bg-color;
        color: $color;
    }

    &:hover {
        @include include-media.media('hover') {
            background-color: color.adjust($bg-color, $lightness: -10%);
            border-color: $bg-color;
            color: $color;
        }
    }

    &:active {
        background-color: color.adjust($bg-color, $lightness: -10%);
    }

    &:focus,
    &:active {
        @include outline.anchor-default-outline(palette.$color-outline--dark);
    }

    &:disabled {
        color: $color;
        background: $bg-color;
        border-color: $bg-color;
    }
}
