@use '../../../abstracts/measurements';
@use '../../../abstracts/variables';
@use '../../../base/page';
@use '../../../abstracts/colors';
@use '../../../anchors/inline';

@use '../../../abstracts/media' as include-media;

main {
    .home__news-events__wrap {
        background: colors.$color-purewhite;
    }

    .home__news-events {
        display: flex;
        gap: measurements.$measure--basic;
        padding-top: measurements.$measure--medium11;
        padding-bottom: 0;

        @include include-media.media('>=small') {
            @include page.standard-box();
        }

        @include include-media.media('<small') {
            @include page.default-margin();
        }

        @include include-media.media('<tablet') {
            flex-direction: column;
        }

        .home__news-events__section {
            flex-basis: 50%;

            .related-content {
                max-width: inherit;
            }

            @include include-media.media('<tablet') {
                flex-basis: 100%;
            }
        }

        .home__news-events__header {
            display: flex;
            border-bottom: variables.$border-width-default
                variables.$border-style-solid colors.$color-brown5;
            justify-content: space-between;
            padding-bottom: measurements.$measure--half;

            h2 {
                margin: 0;
            }
        }

        .home__news-events__header__link {
            display: flex;
            align-items: flex-end;
            margin-bottom: measurements.$measure--quarter;

            a {
                @include inline.anchor-inline(
                    colors.$color-red50,
                    colors.$color-red50,
                    colors.$color-purewhite,
                    colors.$color-red50
                );
            }
        }

        .related-content {
            display: flex;
            list-style: none;
            gap: measurements.$measure--basic;
            flex-wrap: inherit;

            @include include-media.media('<mobile') {
                flex-direction: column;
            }

            .card--news--home,
            .card--event--home {
                flex-basis: 50%;
                margin: 0;

                @include include-media.media('<mobile') {
                    flex-basis: 100%;
                }
            }
        }
    }
}

.no-js {
    main {
        .home__news-events {
            .related-content {
                margin-left: 0;
            }
        }
    }
}
