@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../base/content';
@use '../../base/page';
@use '../../base/typography';
@use '../../layout/grid';
@use '../../abstracts/colors';
@use '../../anchors/outline';
@use '../../anchors/reset';

@use '../../abstracts/media' as include-media;

@mixin selected-select() {
    background-color: colors.$color-purewhite;
    border-color: colors.$color-nearblack;
    color: colors.$color-nearblack;
    font-weight: variables.$font-weight-medium;
}

#search-box {
    form {
        @include include-media.media('>=small') {
            @include page.standard-box();
            @include grid.standard-grid();

            grid-template-rows: repeat(3, auto);
        }

        h2 {
            grid-column: 1 / -1;
        }

        .search-box__filter {
            grid-column: 1 / span 6;
        }

        .search-box__query {
            grid-column: 7 / span 10;
        }

        select {
            padding-right: measurements.$measure--basic;
        }
    }
}

.search-box__text__wrapper {
    background-color: palette.$color-brand-primary;
    padding-bottom: measurements.$measure--small4;

    @include include-media.media('<small') {
        padding-left: measurements.$measure--basic;
        padding-right: measurements.$measure--basic;
    }

    .search-box__text {
        @include include-media.media('>=small') {
            @include page.standard-box();
        }
    }
}

.search-box__cta__wrapper {
    background-color: palette.$color-brand-primary;
    padding-bottom: measurements.$measure--basic;

    @include include-media.media('<small') {
        padding-left: measurements.$measure--basic;
        padding-right: measurements.$measure--basic;
    }

    .search-box__cta__wrapper__border {
        @include include-media.media('>=small') {
            @include page.standard-box();
        }
    }
}

#search-box {
    background-color: palette.$color-brand-primary;
    padding-top: measurements.$measure--small4;
    padding-bottom: measurements.$measure--small4;

    @include include-media.media('<small') {
        padding-left: measurements.$measure--basic;
        padding-right: measurements.$measure--basic;
    }

    h2 {
        color: colors.$color-purewhite;
        padding-bottom: measurements.$measure--basic;
        margin-top: initial;
    }
}

.search-box__select {
    color: colors.$color-nearblack;
    height: auto;
    position: relative;

    @include include-media.media('<small') {
        margin-bottom: measurements.$measure--basic;
    }

    label {
        @include typography.smalltype();

        color: colors.$color-red50;
        display: block;
        font-weight: variables.$font-weight-text;
        padding-bottom: measurements.$measure--basic;
    }

    select {
        @include typography.font-family('default');
        @include typography.body-font-features();
        @include typography.alphatype();

        background-color: colors.$color-purewhite;
        border-color: colors.$color-nearblack;
        border-style: variables.$border-style-solid;
        border-width: variables.$border-width-default;
        border-radius: measurements.$measure--quarter;
        bottom: measurements.$measure--quarter;
        color: colors.$color-nearblack;
        font-weight: variables.$font-weight-text;
        height: measurements.$measure--medium4;
        width: 100%;
        padding-left: 0.5rem;
        padding-right: 0.5rem;
        -webkit-appearance: none;
        -moz-appearance: none;
        appearance: none;

        &:focus {
            @include outline.outline-properties(palette.$color-outline--dark);
            outline-style: variables.$border-style-solid;
        }

        &:hover {
            @include include-media.media('hover') {
                background-color: colors.$color-nearblack;
                color: colors.$color-purewhite;
                font-weight: variables.$font-weight-medium;
                transition: all variables.$transition-duration ease;

                @include include-media.media('reducemotion') {
                    transition: none;
                }
            }
        }
    }

    .fa-chevron-down {
        display: flex;
        justify-content: center;
        position: absolute;
        right: measurements.$measure--basic;
        top: measurements.$measure--threequarters;
        background-color: colors.$color-nearblack;
        color: colors.$color-purewhite;
        border-radius: 100%;
        padding: measurements.$measure--half measurements.$measure--basic;
        pointer-events: none;
        min-width: 30px;
        min-height: 30px;
    }

    &:not(.search-box__select--sort) {
        &.search-box__select--selected {
            select {
                @include selected-select();
            }
        }
    }

    &.search-box__select--sort {
        &.search-box__select--selected {
            select {
                @include include-media.media('<tablet') {
                    @include selected-select();
                }
            }
        }
    }
}

.search-box__query {
    & > div {
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
    }
}

.search-box__query__input {
    @include typography.font-family('default');
    @include typography.body-font-features();
    @include typography.alphatype();

    display: flex;
    flex-grow: 1;
    font-weight: variables.$font-weight-text;
    padding: 0;
    position: relative;

    &:focus-within {
        @include outline.outline-properties(colors.$color-purewhite);
        outline-style: variables.$border-style-solid;
    }

    input {
        @include typography.font-family('default');
        @include typography.body-font-features();
        @include typography.alphatype();

        border-color: colors.$color-nearblack;
        border-style: variables.$border-style-solid;
        border-width: variables.$border-width-default;
        border-radius: measurements.$measure--quarter 0 0
            measurements.$measure--quarter;
        font-style: normal;
        height: measurements.$measure--medium4;
        min-width: 0; // Constrains width in Firefox
        padding-left: measurements.$measure--half;
        padding-right: measurements.$measure--medium5;
        width: 100%;

        @include include-media.media('<mobile') {
            padding-right: measurements.$measure--basic;
        }

        &:focus-within {
            color: colors.$color-gray10;
            font-style: normal;
            font-weight: variables.$font-weight-medium;
            outline: 0;
        }

        &::placeholder {
            font-style: italic;
        }

        &:placeholder-shown {
            color: colors.$color-gray7;
        }
    }

    .search-box__clear {
        @include typography.epsilontype();

        align-items: center;
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        height: measurements.$measure--small5;
        justify-content: center;
        position: absolute;
        right: measurements.$measure--half;
        top: measurements.$measure--quarter;
        width: measurements.$measure--small5;

        &:focus {
            @include outline.outline-properties();
            outline-style: variables.$border-style-solid;
            outline-offset: -#{variables.$border-width-thicker};
        }

        .search-box__clear__text {
            @include mixins.sr-only();
        }

        .icon {
            @include content.xmark-temp-styling;

            letter-spacing: 0;
            line-height: 1;
        }

        &:hover {
            @include include-media.media('hover') {
                background-color: transparent;

                .icon {
                    @include content.xmark-temp-styling-hover;
                }
            }
        }
    }
}

.search-box__query__suggestions {
    background-color: colors.$color-purewhite;
    border-radius: 0 0 measurements.$measure--half measurements.$measure--half;
    border-top: 0;
    border: variables.$border-width-hairline variables.$border-style-solid
        colors.$color-gray2;
    box-shadow: rgba(0, 0, 0, 0.25) 0 measurements.$measure--basic
        measurements.$measure--medium3 (-(measurements.$measure--threequarters));
    color: colors.$color-purewhite;
    font-weight: variables.$font-weight-bold;
    left: 0;
    list-style: none;
    margin-left: 0;
    max-width: unset;
    position: absolute;
    top: measurements.$measure--medium1;
    width: 100%;
    z-index: z-index('above');

    li {
        font-weight: variables.$font-weight-text;
        margin-top: 0;

        button {
            color: palette.$color-text;
            height: 100%;
            padding: measurements.$measure--half measurements.$measure--small4
                measurements.$measure--half measurements.$measure--small4;
            text-align: left;
            width: 100%;

            &:focus {
                outline-color: colors.$color-nearblack;
                outline-offset: (-(variables.$border-width-default));
                outline-style: variables.$border-style-dotted;
                outline-width: variables.$border-width-default;
                text-decoration: underline;
            }

            &:active {
                @include outline.outline-properties();
                outline-style: variables.$border-style-solid;
                outline-offset: 0;
            }

            &:hover {
                @include include-media.media('hover') {
                    background-color: colors.$color-linkblue;
                    color: colors.$color-purewhite;
                    text-decoration: underline;
                }
            }

            .search-box__suggestion {
                font-weight: variables.$font-weight-bold;
            }
        }
    }
}

.search-box__query__suggestions.hide {
    display: none;
}

.finder__clear {
    @include typography.epsilontype();

    align-items: center;
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    height: measurements.$measure--small5;
    justify-content: center;
    position: absolute;
    right: measurements.$measure--half;
    top: measurements.$measure--quarter;
    width: measurements.$measure--small5;

    &:focus {
        @include outline.outline-properties();
        outline-style: variables.$border-style-solid;
        outline-offset: -#{variables.$border-width-thicker};
    }

    .finder__clear__text {
        @include mixins.sr-only();
    }

    .icon {
        @include content.xmark-temp-styling;

        letter-spacing: 0;
        line-height: 1;
    }

    &:hover {
        @include include-media.media('hover') {
            background-color: transparent;

            .icon {
                @include content.xmark-temp-styling-hover;
            }
        }
    }
}

.search-box__query__submit {
    font-size: typography.$font-size--delta;
    background-color: colors.$color-nearblack;
    color: colors.$color-purewhite;
    padding-left: measurements.$measure--basic;
    padding-right: measurements.$measure--basic;
    border-color: colors.$color-nearblack;
    border-style: variables.$border-style-solid;
    border-width: variables.$border-width-default;
    border-radius: 0 measurements.$measure--quarter
        measurements.$measure--quarter 0;

    &:focus {
        @include outline.outline-properties(palette.$color-outline--dark);
        outline-style: variables.$border-style-solid;
    }

    .search-box__query__submit__icon {
        font-weight: variables.$font-weight-medium;
    }
}

.search-box__text {
    color: colors.$color-purewhite;

    a {
        @include reset.anchor-reset-properties;
        color: colors.$color-purewhite;
        text-decoration: underline;
        border-bottom: 0;
        text-decoration: underline;

        &:active {
            @include reset.anchor-reset-properties;
        }

        &:hover {
            @include include-media.media('hover') {
                @include reset.anchor-reset-properties;
                text-decoration: underline;
                color: colors.$color-purewhite;
                border-bottom: 0;
            }
        }

        &:visited,
        &:focus,
        &:active {
            color: colors.$color-purewhite;
            border-bottom: 0;
            text-decoration: underline;
        }

        &:focus,
        &:active {
            @include outline.outline-properties(palette.$color-outline--dark);
            outline-style: variables.$border-style-solid;
        }
    }

    .search-box__text__back-slash {
        padding-left: measurements.$measure--small4;
        padding-right: measurements.$measure--small4;
        color: colors.$color-gray2;
        position: relative;

        &:before {
            background: colors.$color-gray2;
            content: '';
            display: inline-block;
            height: measurements.$measure--small3;
            position: absolute;
            -webkit-transform: rotate(45deg);
            -moz-transform: rotate(45deg);
            -ms-transform: rotate(45deg);
            -o-transform: rotate(45deg);
            transform: rotate(45deg);
            width: variables.$border-width-hairline;
        }

        @include include-media.media('>=mobile', '<small') {
            padding-left: measurements.$measure--small2;
            padding-right: measurements.$measure--small3;
        }
    }

    @include include-media.media('>=mobile') {
        p {
            display: inline;
        }
    }

    @include include-media.media('<mobile') {
        p:first-child {
            margin-top: initial;
        }

        span {
            display: none;
        }
    }
}

.search-box__cta {
    padding-top: measurements.$measure--basic;
    border-top: rgba(0, 0, 0, 0.25) variables.$border-width-hairline
        variables.$border-style-solid;

    @include include-media.media('>tablet') {
        display: flex;
        align-items: center;
    }

    .search-box__cta--text {
        display: flex;
        align-items: center;
    }

    .fa-link {
        display: flex;
        justify-content: center;
        color: colors.$color-purewhite;
        background-color: colors.$color-nearblack;
        border-radius: 100%;
        padding: measurements.$measure--threequarters
            measurements.$measure--small1;
    }

    .search-box__cta__heading {
        color: colors.$color-purewhite;
        margin-top: measurements.$measure--threequarters;
        margin-left: measurements.$measure--half;
        font-weight: variables.$font-weight-bold;
    }

    ul {
        display: flex;
        flex-wrap: wrap;
        list-style: none;
        max-width: initial;
        margin-top: initial;
        margin-left: measurements.$measure--basic;

        @include include-media.media('<=tablet') {
            margin-left: initial;
        }

        li {
            margin-top: initial;
            margin-left: measurements.$measure--basic;
            margin-top: measurements.$measure--half;
            margin-right: measurements.$measure--basic;

            @include include-media.media('<=tablet') {
                margin-left: initial;
            }
        }
    }
}
