@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/variables';
@use 'outline';
@use 'reset';

@mixin cta--border(
    $background: transparent,
    $color: colors.$color-purewhite,
    $border: colors.$color-red50,
    $hover-color: colors.$color-purewhite,
    $hover-border: colors.$color-red70,
    $outline: colors.$color-purewhite,
    $corners: square
) {
    @include reset.anchor-reset();
    @include outline.anchor-default-outline($outline);

    background-color: $background;
    border-style: variables.$border-style-solid;
    border-width: variables.$border-width-hairline;
    display: inline-block;
    padding-bottom: measurements.$measure--half;
    padding-left: measurements.$measure--small2;
    padding-right: measurements.$measure--small2;
    padding-top: measurements.$measure--half;
    transition: background-color variables.$transition-duration--long,
        border-color variables.$transition-duration--long,
        color variables.$transition-duration--long;

    @if $corners == round {
        border-radius: measurements.$measure--quarter;
    }

    &,
    &:focus,
    &:active {
        background-color: $background;
        border-color: $border;
        border-style: variables.$border-style-solid;
        border-width: variables.$border-width-hairline;
        color: $color;
    }

    &:hover {
        @include include-media.media('hover') {
            background-color: $hover-border;
            border-color: $hover-border;
            border-style: variables.$border-style-solid;
            border-width: variables.$border-width-hairline;
            color: $hover-color;
        }
    }
}

@mixin cta--border--subelement(
    $background: transparent,
    $color: colors.$color-purewhite,
    $border: colors.$color-red50,
    $outline: colors.$color-purewhite,
    $hover-color: colors.$color-purewhite,
    $hover-border: colors.$color-red70,
    $hover-outline: colors.$color-purewhite,
    $corners: square,
    $class: 'text'
) {
    @include reset.anchor-reset();

    background-color: $background;
    border-style: variables.$border-style-solid;
    border-width: variables.$border-width-hairline;
    display: inline-block;
    padding-bottom: measurements.$measure--half;
    padding-left: measurements.$measure--small2;
    padding-right: measurements.$measure--small2;
    padding-top: measurements.$measure--half;
    transition: background-color variables.$transition-duration--long,
        border-color variables.$transition-duration--long,
        color variables.$transition-duration--long;

    @if $corners == round {
        border-radius: measurements.$measure--quarter;
    }

    &,
    &:focus,
    &:active {
        background-color: $background;
        border-color: $border;
        border-style: variables.$border-style-solid;
        border-width: variables.$border-width-hairline;
        color: $color;
    }

    &:focus {
        .#{$class} {
            @include outline.outline-properties($outline);
        }
    }

    &:focus:hover {
        .#{$class} {
            outline-color: $hover-outline;
        }
    }

    &:hover {
        @include include-media.media('hover') {
            background-color: $hover-border;
            border-color: $hover-border;
            border-style: variables.$border-style-solid;
            border-width: variables.$border-width-hairline;
            color: $hover-color;
        }
    }
}
