@use '../abstracts/palette';
@use 'outline';
@use 'reset';

@mixin anchor-img($color: palette.$color-outline) {
    @include reset.anchor-reset();

    display: inline-block;

    &:focus {
        @include outline.outline-properties($color);
    }

    &:active {
        @include outline.outline-properties($color);
    }
}
