@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/variables';
@use 'outline';
@use 'reset';

@mixin underline-basic(
    $inactive-color: colors.$color-linkblue,
    $hover-color: colors.$color-linkblue,
    $underline-width: variables.$border-width-thick,
    $outline: colors.$color-linkblue
) {
    @include reset.anchor-reset();
    @include outline.anchor-default-outline($outline);

    color: $inactive-color;
    padding-bottom: variables.$border-width-default;
    text-decoration: underline;

    &:visited {
        color: $inactive-color;
    }

    &:focus {
        color: $inactive-color;
        text-decoration: underline;
    }

    &:hover {
        @include include-media.media('hover') {
            color: $hover-color;
            text-decoration: underline;
        }
    }
}
