@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/palette';
@use 'outline';
@use 'reset';

@mixin anchor-icon(
    $color: palette.$color-text,
    $visited: palette.$color-text,
    $hover: colors.$color-red50,
    $outline: palette.$color-text
) {
    @include reset.anchor-reset-properties();

    border-color: $color;
    color: $color;
    display: inline-block;

    &:hover {
        @include include-media.media('hover') {
            border-color: $hover;

            .icon {
                color: $hover;
            }
        }
    }

    &:active,
    &:focus {
        @include outline.outline-properties($outline);
    }
}
