@use '../../../abstracts/measurements';
@use '../../../abstracts/variables';
@use '../../../base/page';
@use '../../../base/typography';
@use '../../../layout/grid';
@use '../../../abstracts/colors';
@use '../../../anchors/outline';

@use '../../../abstracts/media' as include-media;

.home-banner--promo {
    overflow: hidden;
    position: relative;

    .home-banner--promo__container {
        max-width: typography.$max-line-length;
        @include grid.standard-grid;
        z-index: z-index('above');
        position: relative;

        @include include-media.media('>=small') {
            @include page.standard-box();
        }

        @include include-media.media('<small') {
            @include page.default-margin();
        }
    }

    .home-banner--promo__image {
        position: absolute;
        left: 0;
        right: 0;
        height: 100%;
        top: 0;

        figure {
            margin-top: 0;
        }

        @include include-media.media('<desktop') {
            picture {
                display: flex;
                justify-content: center;
            }
        }

        img {
            width: 100%;

            @include include-media.media('>between', '<desktop') {
                height: 100%;
                max-width: inherit;
                width: auto;
            }
        }
    }

    .home-banner--promo__content {
        grid-column: 1/10;
        background-color: colors.$color-purewhite;
        color: colors.$color-gray10;
        margin-top: measurements.$measure--huge3;
        margin-bottom: measurements.$measure--large4;
        padding: measurements.$measure--medium3;

        @include include-media.media('<desktop') {
            grid-column: 1/12;
        }

        @include include-media.media('<between') {
            grid-column: 1/-1;
            margin-bottom: measurements.$measure--medium5;
            margin-top: 45%;
        }

        @include include-media.media('<tablet') {
            margin-top: 42%;
        }

        @include include-media.media('<tablet') {
            margin-top: 35%;
        }
    }

    .home-banner--promo__content__heading {
        margin-top: measurements.$measure--basic;
        @include typography.thetatype();
    }

    .home-banner--promo__content__text,
    .cta-block {
        margin-top: measurements.$measure--small2;
    }

    .cta-block {
        display: flex;
        flex-direction: row;
        gap: measurements.$measure--basic;
    }

    & ~ .search-box__wrapper .search-box__cta__wrapper {
        display: none;
    }

    ~ .search-box__wrapper .search-box__text__wrapper {
        padding-bottom: measurements.$measure--medium7;
    }

    & ~ * {
        position: relative;
        background: colors.$color-purewhite;
    }

    &.home-banner__theme--default {
        .home-banner--promo__content__heading {
            @include include-media.media('>desktop') {
                font-size: measurements.$measure--medium3;
                line-height: measurements.$measure--medium1;
            }
        }
    }

    &.home-banner__theme--undergraduate {
        .home-banner--promo__content {
            background: colors.$color-purewhite;
            border: variables.$border-width-hairline
                variables.$border-style-solid colors.$color-gray4;
            box-shadow: measurements.$measure--basic
                measurements.$measure--basic 0rem rgba(0, 0, 0, 0.3);
        }

        .home-banner--promo__content__heading {
            color: colors.$color-purewhite;
            background: colors.$color-red50;
            box-decoration-break: clone;
            -webkit-box-decoration-break: clone;
            display: inline;
            padding: 0rem 0.5rem;
            @include typography.zetatype();

            @include include-media.media('>=tablet', '<=between') {
                @include typography.etatype();
            }

            @include include-media.media('>between') {
                @include typography.thetatype();
            }

            line-height: measurements.$measure--medium3;

            @include include-media.media('>=tablet') {
                line-height: measurements.$measure--medium5;
            }
        }

        .home-banner--promo__content__text {
            color: colors.$color-nearblack;
        }

        .cta-block {
            a {
                &:focus,
                &:active {
                    @include outline.anchor-default-outline(
                        colors.$color-nearblack
                    );
                }
            }
        }
    }
}

main {
    .home-banner--promo {
        .cta-block {
            a {
                &:focus,
                &:active {
                    @include outline.anchor-default-outline(
                        colors.$color-nearblack
                    );
                }
            }
        }
    }
}
