@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/cta--basic';
@use '../../base/content';
@use '../../base/page';
@use '../../base/typography';

////
/// CMS editor warning
/// @group patterns
////
.cms-editor-warning {
    display: none;
}

@mixin cms-warning() {
    background-color: colors.$color-red80;
    color: palette.$color-text--dark;
    padding-left: measurements.$measure--half;
    padding-right: measurements.$measure--half;
}

.cms-editor {
    div.cms-editor-warning {
        display: flex;
        grid-column: 1 / 24;
        justify-content: center;

        p {
            @include cms-warning();
            @include typography.alphatype();
            margin-bottom: measurements.$measure--half;
            max-width: typography.$max-line-length;
            padding-top: measurements.$measure--half;
            padding-bottom: measurements.$measure--medium3;
            position: relative;

            &:after {
                @include typography.extrasmalltype();
                bottom: measurements.$measure--half;
                content: 'CMS editor warning';
                font-weight: variables.$font-weight-light;
                position: absolute;
                right: measurements.$measure--half;
            }
        }
    }

    span.cms-editor-warning {
        @include cms-warning();

        display: inline;
    }

    .wrapper--cms-editor-warning-remover {
        @include content.content-style();
        @include page.standard-box();

        margin-bottom: measurements.$measure--small2;
        margin-top: measurements.$measure--small2;
        text-align: center;
    }

    .cms-editor-warning-remover {
        @include cta--basic.cta--basic(
            colors.$color-purewhite,
            colors.$color-red80,
            colors.$color-purewhite,
            colors.$color-red100,
            colors.$color-nearblack,
            round
        );
    }
}
