@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../anchors/discreet';
@use '../../base/typography';

.back-to-top {
    @include typography.smalltype();

    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    justify-content: flex-end;

    .back-to-top__button__arrow {
        background: colors.$color-gray7;
        border-radius: 50%;
        color: colors.$color-purewhite;
        height: measurements.$measure--small4;
        margin-left: 0.625rem;
        padding: measurements.$measure--half;
        text-align: center;
        width: measurements.$measure--small4;

        &:before {
            font-size: 0.625rem;
        }
    }

    &[data-docked='false'] {
        position: absolute;

        a {
            display: inline;
            opacity: 1;
            overflow: hidden;
            position: fixed;
            text-decoration: none;
            z-index: functions.z-index('inpage');
            visibility: visible;

            @include include-media.media('<between') {
                bottom: measurements.$measure--basic;
                right: measurements.$measure--basic;
            }

            @include include-media.media('>=between') {
                bottom: measurements.$measure--threequarters;
                right: measurements.$measure--small1;
            }
        }

        .back-to-top__button__label {
            @include mixins.sr-only();
        }

        .back-to-top__button {
            border-radius: 50%;
            display: flex;
            height: measurements.$measure--medium3;
            width: measurements.$measure--medium3;

            svg {
                display: block;
                position: absolute;
            }

            svg path {
                fill: none;
                stroke: colors.$color-nearblack;
                stroke-width: 5;
                transition: stroke-dashoffset 0ms linear;
            }

            svg circle {
                fill: colors.$color-gray7;
            }
        }

        .back-to-top__button__arrow {
            background: none;
            border-radius: 50%;
            height: 2.556rem;
            margin: auto;
            padding-top: measurements.$measure--half;
            position: relative;
            width: 2.556rem;

            &:before {
                font-size: 0.8125rem;
                display: block;
            }
        }

        .back-to-top__button__arrow__label {
            @include typography.font-family('default');
        }
    }

    &[data-docked='true'] {
        a {
            @include discreet.anchor-discreet--subelement(
                colors.$color-gray4,
                colors.$color-gray4,
                colors.$color-purewhite,
                colors.$color-purewhite,
                colors.$color-red50,
                'back-to-top__button__label'
            );
        }
    }

    &[hidden='true'] {
        a {
            opacity: 0;
            visibility: hidden;
        }
    }

    a {
        border-bottom: none;
        opacity: 1;
        transition: opacity 1s ease;

        &:active {
            outline: variables.$border-width-default
                variables.$border-style-dotted colors.$color-gray6;
            background: none;
            border-bottom-width: 0;
        }

        &:focus {
            outline: variables.$border-width-default
                variables.$border-style-dotted colors.$color-red50;
            border-bottom-width: 0;
        }

        &:hover {
            @include include-media.media('hover') {
                color: colors.$color-gray10;
                background: none;
                text-decoration: none;
                border-bottom-width: 0;
            }
        }

        &:hover .back-to-top__button svg circle {
            @include include-media.media('hover') {
                fill: colors.$color-gray10;
            }
        }
        &:active .back-to-top__button svg circle {
            fill: colors.$color-gray10;
        }

        &:hover .back-to-top__button__label {
            @include include-media.media('hover') {
                color: colors.$color-gray10;
                border-bottom: variables.$border-width-default
                    variables.$border-style-solid colors.$color-gray10;
            }
        }

        &:active .back-to-top__button__label {
            color: colors.$color-gray10;
            border-bottom: variables.$border-width-default
                variables.$border-style-solid colors.$color-gray10;
        }

        & svg {
            display: none;
        }
    }
}

.back-to-top {
    @include include-media.media('print') {
        display: none;
    }
}
