@use '../../../abstracts/media' as include-media;
@use '../../../abstracts/colors';
@use '../../../abstracts/measurements';
@use '../../../abstracts/variables';
@use '../../../anchors/reset';
@use '../../../base/icon';
@use '../../../base/typography';

article .social-icon {
    @include reset.anchor-reset();

    @include icon.zoom-in-icon();
}

.copyLink {
    display: flex;
    justify-content: space-evenly;
    margin-right: 0;
}

.tooltip {
    @include typography.font-family('default');
    color: colors.$color-gray7;
    border: variables.$border-width-hairline solid colors.$color-gray2;
    border-radius: 0.1rem;
    padding: measurements.$measure--quarter measurements.$measure--quarter;
    background-color: colors.$color-gray2;
    transition: all variables.$transition-duration--long;
    font-size: 0.8rem;
    font-weight: bold;
    margin-left: measurements.$measure--basic;
    display: flex;
    flex-direction: column;
    justify-content: center;

    @include include-media.media('<mobile') {
        font-size: 0.5rem;
        width: 9ch;
        margin-left: measurements.$measure--half;
    }
}

article .link-copy {
    position: absolute;
    left: -30000px;
    opacity: 0;
}

.tooltip.successful {
    border-color: colors.$color-gray10;
    background-color: colors.$color-gray10;
    color: colors.$color-purewhite;
}
