@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/palette';
@use '../abstracts/variables';
@use '../anchors/outline';

// ////
/// Icons
/// @group base
////

@mixin zoom-in-icon {
    display: block;
    width: measurements.$measure--small5;
    height: measurements.$measure--small5;
    background-color: colors.$color-nearblack;
    color: colors.$color-purewhite;
    border-radius: 50%;
    border-style: none;
    transition: background-color variables.$transition-duration--long,
        transform variables.$transition-duration--long;

    span {
        height: 100%;
        width: 100%;
        display: flex;
        justify-content: center;
        align-items: center;
    }

    &:before {
        display: flex;
        justify-content: center;
        align-items: center;
        height: 100%;
    }

    &:focus {
        background: colors.$color-nearblack;
        color: colors.$color-purewhite;
    }

    &:focus,
    &:active {
        @include outline.anchor-default-outline(palette.$color-outline);
    }

    &:hover,
    &:active {
        @include include-media.media('hover') {
            transform: scale(1.2);
            background-color: colors.$color-red50;
            color: colors.$color-purewhite;
            background-image: none;
        }
    }

    &:visited {
        color: colors.$color-purewhite;
    }

    &:active,
    &:hover,
    &:focus,
    &:visited {
        border-bottom-style: none;
    }
}
