@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/palette';
@use '../abstracts/variables';
@use 'outline';
@use 'reset';

@mixin anchor-discreet-before($border-hover: colors.$color-red50) {
    &:before {
        background: $border-hover;
        bottom: -#{variables.$border-width-default};
        content: '';
        display: block;
        height: variables.$border-width-default;
        left: 0;
        opacity: 0;
        position: absolute;
        transition: opacity variables.$transition-duration
                variables.$transition-function,
            width variables.$transition-duration--long
                variables.$transition-function;
        width: 0;

        @include include-media.media('reducemotion') {
            transition: none;
        }
    }
}

@mixin anchor-discreet(
    $color: palette.$color-text,
    $visited: palette.$color-text,
    $hover: palette.$color-text,
    $outline: palette.$color-outline,
    $border-hover: colors.$color-red50
) {
    @include reset.anchor-reset();
    @include outline.anchor-default-outline($outline);
    @include anchor-discreet-before($border-hover);

    background-image: none;
    border-bottom-color: $color;
    border-bottom-style: variables.$border-style-solid;
    border-bottom-width: variables.$border-width-default;
    color: $color;
    position: relative;

    &:before {
        transition: opacity variables.$transition-duration
                variables.$transition-function,
            width variables.$transition-duration--long
                variables.$transition-function;
    }

    &:focus {
        border-bottom-color: $color;
        border-bottom-style: variables.$border-style-solid;
        border-bottom-width: variables.$border-width-default;
        color: $color;
    }

    &:visited {
        border-bottom-color: $visited;
        border-bottom-style: variables.$border-style-solid;
        border-bottom-width: variables.$border-width-default;
        color: $visited;
    }

    &:hover {
        @include include-media.media('hover') {
            background-image: none;
            border-bottom-color: $hover;
            border-bottom-style: variables.$border-style-solid;
            border-bottom-width: variables.$border-width-default;
            color: $hover;

            &:before {
                opacity: 1;
                width: 100%;
                transition: opacity variables.$transition-duration
                        variables.$transition-function,
                    width variables.$transition-duration--long
                        variables.$transition-function;
            }
        }
    }

    &:active {
        border-bottom-color: $hover;
        border-bottom-style: variables.$border-style-solid;
        border-bottom-width: variables.$border-width-default;
    }
}

