@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/content';
@use '../../base/typography';
@use '../reset';
@use '../../abstracts/colors';

@use './card--mixin';
@use '../../abstracts/media' as include-media;

.card--event--home {
    .card--event--home__anchor {
        display: flex;
        flex-direction: column;
        overflow: hidden;
        @include reset.anchor-reset();
        @include card--mixin.card-anchor-colors();
        background-color: colors.$color-purewhite;

        @include include-media.media('reducemotion') {
            transition: none;
        }

        &,
        &:focus,
        &:active,
        &:visited {
            border: none;
            outline-style: variables.$border-style-solid;
        }

        &:hover {
            background-color: inherit;
            @include include-media.media('hover') {
                border: none;
            }

            .card--event--home__thumbnail img {
                transform: scale(1.1);
            }
        }
    }

    .card--event--home__thumbnail {
        position: relative;
        line-height: 0;
        overflow: hidden;

        img {
            transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
        }
    }

    .card--event--home__date-label {
        position: absolute;
        @include typography.betatype();
        align-self: flex-start;
        background-color: colors.$color-red50;
        color: colors.$color-purewhite;
        display: inline-block;
        font-weight: variables.$font-weight-bold;
        left: 0;
        bottom: 0;
        margin-top: 0;
        position: absolute;
        padding: measurements.$measure--half measurements.$measure--basic;
        display: flex;
        flex-direction: column;
        text-align: center;
        @include content.heading-style();

        @include include-media.media('reducemotion') {
            transition: none;
        }

        span {
            font-weight: variables.$font-weight-text;
            margin-left: auto;
            margin-right: auto;
        }
    }

    .card--event--home__text {
        padding-bottom: measurements.$measure--basic;
        padding-top: measurements.$measure--quarter;
        background-color: colors.$color-purewhite;
    }

    .card--event--home__heading {
        @include content.h5style();
        text-decoration: underline;
        display: inline;
        max-width: unset;
        color: colors.$color-nearblack;
        text-decoration-thickness: 12%;
    }

    .card--event--home__date {
        @include typography.smalltype();
        margin-top: variables.$content-element-margin;
    }
}
