@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../base/typography';

@use './card--mixin';

.card--event {
    .card__anchor {
        @include mixins.box-shadow();

        background-color: colors.$color-purewhite;
        position: relative;

        &,
        &:focus,
        &:active,
        &:visited {
            border: none;
        }

        &:hover {
            @include include-media.media('hover') {
                @include mixins.box-shadow-darker();

                border: none;
            }
        }

        .card--event__label--event {
            @include typography.smalltype();

            color: colors.$color-gray7;
            font-style: italic;
            margin-left: measurements.$measure--basic;
            margin-top: measurements.$measure--basic;
        }

        .card--event__label--event + .card__thumbnail {
            margin-top: variables.$content-element-margin;
        }

        .card--event__label--shortdate {
            @include typography.smalltype();

            align-self: flex-start;
            background-color: colors.$color-red50;
            color: colors.$color-purewhite;
            display: inline-block;
            font-weight: variables.$font-weight-bold;
            left: 0;
            margin-top: 0;
            position: absolute;
            padding: measurements.$measure--half;
            top: measurements.$measure--medium1;
            transition: background-color variables.$transition-duration ease-in;

            @include include-media.media('reducemotion') {
                transition: none;
            }

            span {
                font-weight: variables.$font-weight-text;
            }

            // When no Event label, position short date at top of card
            &:first-child {
                top: 0;
            }

            &:first-child + .card__details__text {
                margin-top: measurements.$measure--medium1;
            }
        }

        &:hover {
            .card--event__label--shortdate {
                @include include-media.media('hover') {
                    background-color: colors.$color-red70;
                }
            }
        }

        .card--event__label--event + .card--event__label--shortdate,
        .card--event__label--shortdate + .card__thumbnail {
            margin-top: variables.$content-element-margin;
        }

        .card__details__text {
            margin-top: measurements.$measure--medium4;
            padding-bottom: measurements.$measure--basic;
            padding-top: variables.$heading-margin;
        }

        .card--event__label--shortdate
            .card--event__label--event
            + .card--event__label--shortdate {
            top: measurements.$measure--medium1;
        }

        .card--event__label--event
            + .card__thumbnail
            + .card--event__label--shortdate {
            top: measurements.$measure--medium7;
        }

        .card__thumbnail ~ .card__details__text {
            margin-top: 0;
        }

        .card__type {
            @include typography.smalltype();
            margin-top: variables.$content-element-margin;
            color: colors.$color-gray7;
        }

        .card--event__divider {
            color: colors.$color-red50;
        }

        &:after {
            content: unset;
            display: none;
        }
    }

    &.card--landscape {
        @include card--mixin.landscape-card();

        .card--event__label--event
            + .card--event__label--shortdate
            + .card__details__text {
            margin-top: measurements.$measure--large4;
        }
    }

    @include include-media.media('>mobile', '<small') {
        @include card--mixin.landscape-card();

        .card--event__label--event
            + .card--event__label--shortdate
            + .card__details__text {
            margin-top: measurements.$measure--large4;
        }
    }
}
