@use 'sass:math';
@use '../../abstracts/colors';
@use '../../abstracts/measurements';

.link-decorator {
    margin-right: measurements.$measure--half;
}

// Link decorator not part of an anchor
:not(a) > .link-decorator {
    color: colors.$color-red50;
}

// Link decorator part of an, e.g. CTA
a .link-decorator {
    margin-top: calc(
        #{measurements.$measure--quarter} + (#{math.div(
                        measurements.$measure--quarter,
                        2
                    )})
    );
}

.inline-external-link {
    margin-left: measurements.$measure--half;
}
