@forward 'page-mixins';
@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/mixins';
@use '../abstracts/palette';
@use '../abstracts/variables';
@use '../layout/grid';
@use 'page-mixins';

////
/// Page
/// @group base
////
html {
    background-color: palette.$color-bg;
    color: palette.$color-text;
    box-sizing: border-box;
    min-height: 100%;
    overflow-x: hidden;
    overflow-y: scroll;
    scroll-behavior: smooth;

    @include include-media.media('reducemotion') {
        scroll-behavior: auto;
    }
}

body {
    min-height: 100vh;
    position: relative;
    scroll-behavior: smooth;

    @include include-media.media('reducemotion') {
        scroll-behavior: auto;
    }
}

*,
*:before,
*:after {
    box-sizing: inherit;
}

.logo {
    display: block;
    width: measurements.$measure--medium7;
}

@mixin default-margin() {
    margin-left: measurements.$measure--basic;
    margin-right: measurements.$measure--basic;
    max-width: variables.$width--max;

    @include include-media.media('>between') {
        margin-left: measurements.$measure--small2;
        margin-right: measurements.$measure--small2;
    }
}

@mixin default-padding() {
    @include page-mixins.default-padding();
}

@mixin standard-box() {
    @include default-margin();
    @include default-padding();

    @include include-media.media('>large') {
        margin-left: auto;
        margin-right: auto;
    }
}

main {
    article {
        background-color: colors.$color-purewhite;
        grid-column: 1/-1;
        height: max-content;
        &:not(.container--no-shadow) {
            @include mixins.box-shadow();
        }
        .content-wrapper {
            @include grid.standard-grid();
        }

        .content {
            @include default-margin();
            grid-column: 1/-1;
            padding: measurements.$measure--half;
            @include include-media.media('>=small') {
                grid-column: 2/-2;
                margin: 0;
            }
        }
    }

    .navigation--secondary {
        grid-column: 1 / span 6;

        & + article {
            grid-column: 7 / span 18;
        }
    }
}

.js {
    .nojs-only {
        display: none;
    }
}
