@use 'sass:meta';
@use '../../abstracts/media' as include-media;
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/content';
@use '../../base/typography';
@use '../reset';

@use './card--mixin';

.card {
    list-style-type: none;
    max-width: unset;

    .card__anchor {
        @include reset.anchor-reset();
        @include card--mixin.card-anchor-colors();

        display: flex;
        flex-direction: column;
        overflow: hidden;
        position: relative;
        transition: background-color variables.$transition-duration ease-in;

        @include include-media.media('reducemotion') {
            transition: none;
        }

        &,
        &:focus,
        &:active,
        &:visited {
            border-width: variables.$border-width-hairline;
            border-style: variables.$border-style-solid;
        }

        &:hover {
            @include include-media.media('hover') {
                border-style: variables.$border-style-solid;
                border-width: variables.$border-width-hairline;

                .card__thumbnail {
                    transform: scale(1.02);
                }
            }
        }

        &:after {
            @include typography.font-family('sharp');

            align-items: center;
            bottom: 0;
            content: '\f178';
            display: flex;
            font-weight: variables.$font-weight-light;
            height: measurements.$measure--small4;
            justify-content: center;
            position: absolute;
            right: 0;
            text-align: center;
            transition: background-color variables.$transition-duration ease-in;
            width: measurements.$measure--small4;

            @include include-media.media('reducemotion') {
                transition: none;
            }
        }

        .card__thumbnail {
            align-self: flex-start;
            transition: transform variables.$transition-duration ease-in-out;
            width: 100%;

            @include include-media.media('reducemotion') {
                transition: none;
            }
        }

        .card__heading {
            border-bottom-style: variables.$border-style-solid;
            border-bottom-width: variables.$border-width-default;

            .icon {
                margin-left: measurements.$measure--half;
            }
        }
    }

    .card__details {
        .card__details__text {
            padding-bottom: measurements.$measure--medium3;
            padding-left: measurements.$measure--basic;
            padding-right: measurements.$measure--basic;
            padding-top: measurements.$measure--basic;
        }

        .card__thumbnail {
            & + .card__details__text {
                padding-top: variables.$heading-margin;
            }
        }

        .card__heading {
            @include content.h5style();

            display: inline;
            max-width: unset;
        }

        .card__type {
            @include typography.alphatype();

            margin-top: 0;
        }

        .card__description {
            @include content.content-style();
        }

        .card__tag {
            @include typography.smalltype();

            max-width: unset;

            & + .card__tag {
                margin-top: 0;
            }

            .icon {
                margin-right: measurements.$measure--half;
            }
        }
    }
}

