@use '../../../abstracts/measurements';
@use '../../../abstracts/palette';
@use '../../../abstracts/variables';
@use '../../../base/page';
@use '../../../abstracts/colors';

@use '../../../abstracts/media' as include-media;

@keyframes moveUp {
    0% {
        transform: translateX(-100%);
    }
    100% {
        transform: translateX(0%);
    }
}

@keyframes moveUpAndRotate {
    0% {
        transform: translateX(100%) rotate(180deg);
    }
    100% {
        transform: translateX(0%) rotate(180deg);
    }
}

main {
    .home__pathway {
        position: relative;
        background: colors.$color-purewhite;
        padding-bottom: measurements.$measure--half;

        @include include-media.media('<small') {
            .pathway {
                .pathway__cards {
                    .card--pathway {
                        &:not(:nth-of-type(1)) {
                            margin-top: measurements.$measure--small1;
                            flex-direction: row;
                            flex-wrap: nowrap;
                        }
                    }
                }
            }
        }

        @include include-media.media('>=1080p') {
            .triangle__block {
                display: none;
            }
        }

        @include include-media.media('<small') {
            .pathway {
                @include page.default-margin();

                .card--pathway__anchor {
                    box-shadow: 0 0 measurements.$measure--small2
                        rgba(0, 0, 0, 0.15);
                }
            }
        }

        @include include-media.media('>=small') {
            .pathway {
                @include page.standard-box();

                .card--pathway__anchor {
                    box-shadow: 0 0 measurements.$measure--basic
                        rgba(0, 0, 0, 0.15);
                }
            }
        }

        // Generic

        .triangle__block--left {
            position: absolute;
        }

        // VI
        &.in-view {
            .triangle__block--left {
                animation: moveUp variables.$transition-duration--longer1;
            }

            .triangle__block--right {
                animation: moveUpAndRotate
                    variables.$transition-duration--longer1;
            }
        }

        // Card block
        .pathway {
            .pathway__cards {
                display: grid;
                grid-template-columns: repeat(3, 1fr);
                max-width: unset;
                grid-column-gap: measurements.$measure--small2;
                margin: 0 0 measurements.$measure--small4 0;
                padding-top: measurements.$measure--basic;
                position: relative;
                z-index: z-index('above');
                @include include-media.media('<small') {
                    display: block;
                }
            }

            .card--pathway {
                list-style-type: none;
                opacity: 0;
                transition: opacity variables.$transition-duration--longer3;
                margin-top: measurements.$measure--basic;
                z-index: z-index('above');
                background: colors.$color-purewhite;

                &.in-view {
                    opacity: 1;
                }

                .card--pathway__anchor {
                    display: block;
                    background-image: none;
                    border: 0;
                    height: 100%;
                    transition: transform variables.$transition-duration--long
                            cubic-bezier(0.4, 0, 0.2, 1),
                        box-shadow variables.$transition-duration--long
                            cubic-bezier(0.4, 0, 0.2, 1);

                    &:focus,
                    &:active {
                        outline-style: variables.$border-style-solid;
                        background: transparent;
                    }

                    &:hover {
                        @include include-media.media('hover') {
                            .card--pathway__img {
                                transform: scale(1.1);
                            }
                            transform: translateY(-2px);
                            box-shadow: 0 0 measurements.$measure--basic
                                rgba(0, 0, 0, 0.25);
                        }
                    }

                    &.card--pathway__border {
                        border-top: measurements.$measure--half
                            variables.$border-style-solid
                            palette.$color-brand-primary;
                    }

                    .wrap--card--pathway__heading {
                        position: relative;
                        padding-left: measurements.$measure--basic;
                        flex-basis: 100%;
                    }
                }
            }

            .wrap--icon {
                display: flex;
                margin-bottom: measurements.$measure--threequarters;

                .wrap--icon__img {
                    height: measurements.$measure--medium1;
                }
            }

            .wrap--card--pathway__img {
                overflow: hidden;
                line-height: 0;

                .card--pathway__img {
                    transition: transform variables.$transition-duration--long
                        cubic-bezier(0.4, 0, 0.2, 1);
                }

                & + .card--pathway__txt {
                    padding-top: measurements.$measure--basic;
                }
            }

            .card--pathway__txt {
                padding: measurements.$measure--small2;
                color: initial;
            }

            .card--pathway__heading {
                font-weight: variables.$font-weight-medium;
                display: inline;
                text-decoration: underline;
            }

            .card--pathway__desc {
                font-weight: variables.$font-weight-normal;
            }

            @include include-media.media('<mobile') {
                .card--pathway {
                    .card--pathway__anchor {
                        .wrap--icon {
                            flex-wrap: wrap;
                        }

                        .wrap--icon__img {
                            margin-right: measurements.$measure--quarter;
                        }

                        .line {
                            border-top: variables.$border-width-thicker
                                variables.$border-style-solid
                                palette.$color-brand-primary;
                            flex: 1;
                            margin: auto;
                        }

                        .wrap--card--pathway__heading {
                            padding: measurements.$measure--half 0 0 0;
                            flex-basis: 100%;
                        }
                    }
                }
            }

            @include include-media.media('>=mobile', '<small') {
                .card--pathway__content {
                    display: flex;
                }

                .wrap--icon {
                    display: block;
                }

                .card--pathway {
                    .card--pathway__anchor {
                        .wrap--card--pathway__heading {
                            padding-left: 0;
                        }
                    }

                    .wrap--card--pathway__img {
                        margin: measurements.$measure--basic;
                        flex-basis: 40%;

                        & + .card--pathway__txt {
                            padding: measurements.$measure--basic
                                measurements.$measure--small2
                                measurements.$measure--small2
                                measurements.$measure--half;
                            flex-basis: 60%;
                        }
                    }

                    .wrap--icon__img {
                        margin-bottom: measurements.$measure--quarter;
                    }
                }
            }
        }
    }
}
.no-js {
    main {
        .home__pathway {
            .pathway {
                .card--pathway {
                    opacity: 1;
                }
            }
        }
    }
}
