@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';

.related-content {
    .card--profile {
        .card__details {
            display: flex;
            flex-wrap: nowrap;

            @include include-media.media('<tablet') {
                flex-direction: column;
            }

            @include include-media.media('>=tablet') {
                flex-direction: row;
            }
        }

        .card__thumbnail {
            padding-left: measurements.$measure--basic;
            padding-top: measurements.$measure--basic;
        }
    }
}

.finder__results,
.search__results {
    .card--profile {
        .card__details {
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;
        }
    }
}

.card--profile {
    .card__details {
        .card__thumbnail {
            flex-shrink: 0;
            height: measurements.$measure--huge5;
            width: measurements.$measure--huge5;
        }

        .card__type {
            color: colors.$color-red50;
        }
    }
}
