@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../anchors/inline';
@use '../../anchors/mixins-cta';
@use '../../base/content';
@use '../../base/page';
@use '../../base/typography';

.wrapper--feedback {
    @include include-media.media('>=small') {
        @include page.standard-box();
    }
}

.feedback {
    @include include-media.media('print') {
        display: none;
    }

    @include mixins.box-shadow();
    margin: measurements.$measure--small2 0;
    @include typography.alphatype();

    background-color: colors.$color-purewhite;
    display: block;
    padding-bottom: measurements.$measure--half;
    padding-left: measurements.$measure--small2;
    padding-right: measurements.$measure--small2;
    padding-top: measurements.$measure--half;
    grid-column: 1/-1;

    @include include-media.media('<small') {
        @include page.default-margin();
    }

    @include include-media.media('>=between') {
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        justify-content: space-between;
    }

    @include include-media.media('>=large') {
        @include page.standard-box();
        width: 100%;
    }

    .feedback__form-link,
    .feedback__direct {
        @include content.content-style();
        margin-top: 0;
        max-width: unset;
    }

    .feedback__direct {
        legend {
            float: left; // unavoidable float because legend sucks
            margin-bottom: measurements.$measure--basic;
            margin-right: measurements.$measure--half;
            margin-top: measurements.$measure--basic;
        }

        p {
            margin-bottom: measurements.$measure--basic;
            margin-top: measurements.$measure--basic;
        }

        .feedback__direct__buttons {
            display: inline-flex;
            flex-direction: row;
            flex-wrap: nowrap;
        }

        button {
            @include mixins-cta.cta-basic-light-bg(
                colors.$color-purewhite,
                colors.$color-nearblack
            );
            box-shadow: none;
            margin-bottom: measurements.$measure--half;
            margin-top: measurements.$measure--half;
            border-color: colors.$color-gray3;

            &:active,
            &:focus {
                border-color: colors.$color-gray3;
            }

            @include include-media.media('<=mobile') {
                display: inline-block;
            }

            & + button {
                margin-left: measurements.$measure--basic;
            }
        }
    }

    .feedback__form-link {
        margin-bottom: measurements.$measure--basic;
        margin-top: measurements.$measure--basic;

        a {
            @include inline.anchor-inline();
        }
    }
}
