////
/// Anchor mixins
/// @group abstracts
////
@use 'reset';
@use 'outline';
@use 'hover';
@use 'ghost-animation';
@use 'inline';
@use 'img';
@use 'img-linked-pattern';
@use 'pagination';
@use 'discreet';
@use 'underline-basic';
@use 'underline-transition';
@use 'icon';
@use 'navigation';
@use 'cta--basic';
@use 'cta--border';
@use 'menu';
@use 'pathway-card';
@use 'card/card';
@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/palette';
@use '../abstracts/variables';
@use '../base/content';
@use 'mixins-cta';

@mixin cta-like-anchors(
    $background: colors.$color-purewhite,
    $color: colors.$color-red50
) {
    @include mixins-cta.cta-primary-icon-light-bg($background, $color);
    @include content.h5style();

    border-radius: 0;
    border: variables.$border-width-default variables.$border-style-solid $color;
    box-shadow: none;
    height: 100%;
    margin-top: 0;
    width: 100%;

    &:after {
        align-items: center;
        display: flex;
        position: relative;
        right: measurements.$measure--half;
    }

    span {
        color: colors.$color-gray11;
        margin: auto 0;
        width: 100%;
        &:active {
            color: $background;
        }
    }

    .cta-like-anchor__text {
        span:nth-child(2) {
            @include content.content-style();
        }
    }

    &:visited {
        border: variables.$border-width-default variables.$border-style-solid
            $color;
    }

    &:focus {
        border: variables.$border-width-default variables.$border-style-solid
            $color;
        span {
            color: colors.$color-gray11;
        }
        &:after {
            color: colors.$color-gray11;
        }
    }

    &:active {
        background: $color;
    }

    &:hover {
        @include include-media.media('hover') {
            span {
                color: $background;
            }
            &:after {
                color: $background;
            }
        }
    }
}

@mixin anchor-span() {
    @include reset.anchor-reset();
    @include hover.anchor-hover-background();
    color: palette.$color-inline-link;

    span {
        border-bottom-color: palette.$color-inline-link;
        border-bottom-style: variables.$border-style-solid;
        border-bottom-width: variables.$border-width-default;
    }

    &:focus {
        color: palette.$color-inline-link;

        span {
            outline-color: palette.$color-outline;
            outline-offset: variables.$border-width-thick;
            outline-style: variables.$border-style-dotted;
            outline-width: variables.$border-width-default;
        }
    }

    &:hover {
        @include include-media.media('hover') {
            color: palette.$color-text--dark;

            span {
                outline: none;
            }
        }
    }

    &:active {
        background-color: palette.$color-inline-link;
        color: palette.$color-text--dark;

        span {
            outline-color: palette.$color-outline--dark;
            outline-offset: variables.$border-width-thick;
            outline-style: variables.$border-style-dotted;
            outline-width: variables.$border-width-default;
        }
    }
}

@mixin anchor-button() {
    @include reset.anchor-reset();
    color: palette.$color-inline-link;
    border: none;

    &:focus {
        color: palette.$color-text;
        outline-color: palette.$color-outline;
        outline-width: variables.$border-width-default;
        outline-style: variables.$border-style-dotted;
    }

    &:hover {
        @include include-media.media('hover') {
            background-image: none;
            color: palette.$color-text;
        }
    }

    &:active {
        outline-color: palette.$color-outline;
        outline-width: variables.$border-width-default;
        outline-style: variables.$border-style-dotted;
        outline-offset: variables.$border-width-thick;
    }

    &[disabled] {
        color: palette.$color-text;
        &:focus,
        &:hover,
        &:active {
            outline: none;
        }
    }
}

article {
    a {
        @include inline.anchor-inline();
    }
}
