@use 'sass:math';
@use '../../../abstracts/measurements';
@use '../../../abstracts/palette';
@use '../../../abstracts/variables';
@use '../../../base/page';
@use '../../../base/typography';
@use '../../../abstracts/colors';

@use '../../../abstracts/media' as include-media;

@keyframes fadeIn {
    0% {
        opacity: 0;
    }
    100% {
        opacity: 1;
    }
}

@keyframes scaleIn {
    0% {
        transform: scale(1.15);
    }
    100% {
        transform: scale(1.1);
    }
}

main {
    .home__social {
        grid-column: 1/-1;
        position: relative;

        .row {
            display: flex;
        }

        .wrap--social__img {
            overflow: hidden;

            &:nth-of-type(1) {
                .social__img {
                    &.in-view {
                        animation: fadeIn 1.8s 0s, scaleIn 1.8s 0s;
                        animation-fill-mode: forwards;
                    }
                }
            }

            &:nth-of-type(2) {
                .social__img {
                    &.in-view {
                        animation: fadeIn 1.8s 0.1s, scaleIn 1.8s 0.1s;
                        animation-fill-mode: forwards;
                    }
                }
            }

            &:nth-of-type(3) {
                .social__img {
                    &.in-view {
                        animation: fadeIn 1.8s 0.2s, scaleIn 1.8s 0.2s;
                        animation-fill-mode: forwards;
                    }
                }
            }

            &:nth-of-type(4) {
                .social__img {
                    &.in-view {
                        animation: fadeIn 1.8s 0.3s, scaleIn 1.8s 0.3s;
                        animation-fill-mode: forwards;
                    }
                }
            }

            &:nth-of-type(5) {
                .social__img {
                    &.in-view {
                        animation: fadeIn 1.8s 0.4s, scaleIn 1.8s 0.4s;
                        animation-fill-mode: forwards;
                    }
                }
            }
        }

        .social__img {
            opacity: 0;
            filter: brightness(0.65);
        }

        .card {
            position: absolute;
            background: colors.$color-purewhite;
            padding: measurements.$measure--medium6
                measurements.$measure--medium2;
            transition: top 0.3s;
            z-index: z-index('above');
        }

        .card__content__body {
            padding-bottom: measurements.$measure--basic;
            margin-bottom: measurements.$measure--basic;
        }

        .card__content__heading {
            margin-top: 0;
        }

        .card__post-strap {
            .icon__wrapper {
                background-color: palette.$color-brand-primary;
                border-radius: measurements.$measure--basic;
                color: colors.$color-purewhite;
                display: inline-flex;
                height: measurements.$measure--small4;
                width: measurements.$measure--small4;
                margin-right: measurements.$measure--half;

                .icon {
                    margin: auto;
                    &.fa-instagram {
                        &:before {
                            @include typography.gammatype();
                        }
                    }
                }

                .line {
                    margin-bottom: measurements.$measure--small1;
                }
            }

            a.anchor-discreet {
                color: palette.$color-brand-primary;
                border-bottom-color: palette.$color-brand-primary;
                font-weight: variables.$font-weight-medium;
                bottom: math.div(measurements.$measure--quarter, 2);

                &:hover {
                    @include include-media.media('hover') {
                        &::before {
                            opacity: 0;
                            transition: none;
                        }
                    }
                }

                &:focus {
                    outline-style: solid;
                }
            }
        }

        @include include-media.media('<mobile') {
            .card {
                padding-left: measurements.$measure--basic;
                padding-right: measurements.$measure--basic;
            }
            .wrap--social__img {
                &:nth-of-type(3) {
                    display: none;
                }
            }
        }

        @include include-media.media('<tablet') {
            .card {
                padding-left: measurements.$measure--small4;
                padding-right: measurements.$measure--small4;
            }
            .wrap--social__img {
                &:nth-of-type(4),
                &:nth-of-type(5) {
                    display: none;
                }
            }
        }

        @include include-media.media('<small') {
            .card {
                padding-left: measurements.$measure--medium1;
                padding-right: measurements.$measure--medium1;
                @include page.default-margin();
                top: 50%;
                transform: translateY(-50%);
            }
        }

        @include include-media.media('>=small', '<1080p') {
            .wrap--card {
                @include page.standard-box();
                max-width: variables.$width--max;
            }
        }

        @include include-media.media('>=small') {
            .wrap--card {
                @include page.standard-box();
                max-width: variables.$width--max;
            }

            .card {
                &.in-view {
                    top: 10rem;
                }
                &:not(.in-view) {
                    opacity: 0;
                    top: 17rem;
                }
            }
        }

        @include include-media.media('>=1080p') {
            .wrap--card {
                padding-left: measurements.$measure--medium7;
                padding-right: measurements.$measure--medium7;
                margin: 0;
                width: 30vw;
            }

            // Limit image block width, similar to other content elements on page
            @include page.standard-box();
            width: variables.$width--max;
        }
    }
}

.no-js {
    main {
        .home__social {
            .card {
                opacity: 1;
            }
        }

        .home__social {
            .social__img {
                opacity: 1;
                transform: scale(1.1);
            }
        }
    }
}
