@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/content';
@use '../../base/typography';

.card--testimonial {
    .card__details {
        display: flex;
        flex-direction: column;
        position: relative;

        @include include-media.media('>tablet') {
            flex-direction: row;
        }

        .card__thumbnail {
            margin-top: measurements.$measure--small4;

            @include include-media.media('<=tablet') {
                position: absolute;
                right: 0;
                bottom: -(measurements.$measure--half);
                margin-top: -(measurements.$measure--medium3);
            }

            @include include-media.media('>tablet') {
                align-self: start;
                margin-left: measurements.$measure--basic;
                margin-right: measurements.$measure--small4;
            }

            img {
                width: measurements.$measure--large4;
                max-width: none;
                @include include-media.media('<=tablet') {
                    width: measurements.$measure--medium7;
                }
            }
        }

        .card__details__text {
            padding-bottom: measurements.$measure--basic;
        }

        .card--testimonial__author {
            .card__tag {
                @include typography.smalltype();

                color: colors.$color-gray7;
                font-weight: variables.$font-weight-bold;
            }
        }

        .card--testimonial__quote {
            margin-top: measurements.$measure--small4;
            position: relative;
            padding-left: measurements.$measure--threequarters;

            p {
                @include content.standfirst();
                /**
               * Increasing the font size of the quotation marks means that the
               * lines containing them are slightly taller, resulting in uneven
               * spacing.
               *
               * Increase the spacing throughout to make space and so it’s at
               * equal throughout.
               **/
                line-height: typography.$line-height-ratio--override--zeta;
                color: colors.$color-gray10;

                &:first-child {
                    margin-top: 0;
                }
            }

            span {
                position: relative;
            }

            &:before,
            &:after {
                @include content.standfirst();
                @include typography.zetatype();
                color: colors.$color-pink90;
                display: inline;
                /**
               * Quotation mark line height equal to other lines, even though
               * the font size is greater.
               **/
                line-height: typography.$line-height-ratio--override--alpha;
            }

            &:before {
                content: '“';
                left: 0;
                position: absolute;
                top: #{- (measurements.$measure--half)};
            }

            &:after {
                content: '”';
                right: auto;
                position: absolute;
                bottom: 0;
            }
        }
    }
}
