@use '../abstracts/media' as include-media;
@use '../abstracts/palette';
@use '../abstracts/variables';
@use 'hover';
@use 'outline';
@use 'reset';

@mixin anchor-inline(
    $color: palette.$color-inline-link,
    $visited: palette.$color-inline-link--visited,
    $hover: palette.$color-text--dark,
    $outline: palette.$color-outline
) {
    @include reset.anchor-reset();
    @include hover.anchor-hover-background($color);
    @include outline.anchor-default-outline($outline);

    border-bottom-color: $color;
    border-bottom-style: variables.$border-style-solid;
    border-bottom-width: variables.$border-width-default;
    color: $color;

    &:visited {
        border-bottom-color: $visited;
        border-bottom-style: variables.$border-style-solid;
        border-bottom-width: variables.$border-width-default;
        color: $visited;
    }

    &:focus {
        border-bottom-color: $color;
        border-bottom-style: variables.$border-style-solid;
        border-bottom-width: variables.$border-width-default;
        color: $color;
    }

    &:hover {
        @include include-media.media('hover') {
            border-bottom-color: $color;
            border-bottom-style: variables.$border-style-solid;
            border-bottom-width: variables.$border-width-default;
            color: $hover;
        }
    }

    &:active {
        background-color: $color;
        border-bottom-color: $color;
        border-bottom-style: variables.$border-style-solid;
        border-bottom-width: variables.$border-width-default;
        color: $hover;
    }
}

@mixin anchor-inline--subelement(
    $color: palette.$color-inline-link,
    $visited: palette.$color-inline-link--visited,
    $hover: palette.$color-text--dark,
    $outline: palette.$color-outline,
    $class: 'inline-text'
) {
    @include reset.anchor-reset();
    @include outline.anchor-default-outline($outline);

    .#{$class} {
        @include reset.anchor-reset();
        @include hover.anchor-hover-background($color);

        border-bottom-color: $color;
        border-bottom-style: variables.$border-style-solid;
        border-bottom-width: variables.$border-width-default;
        color: $color;
    }

    &:visited {
        .#{$class} {
            border-bottom-color: $visited;
            border-bottom-style: variables.$border-style-solid;
            border-bottom-width: variables.$border-width-default;
            color: $visited;
        }
    }

    &:focus {
        .#{$class} {
            border-bottom-color: $color;
            border-bottom-style: variables.$border-style-solid;
            border-bottom-width: variables.$border-width-default;
            color: $color;
        }
    }

    &:hover {
        @include include-media.media('hover') {
            .#{$class} {
                border-bottom-color: $color;
                border-bottom-style: variables.$border-style-solid;
                border-bottom-width: variables.$border-width-default;
                color: $hover;
            }
        }
    }

    &:active {
        .#{$class} {
            background-color: $color;
            border-bottom-color: $color;
            border-bottom-style: variables.$border-style-solid;
            border-bottom-width: variables.$border-width-default;
            color: $hover;
        }
    }
}
