@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../base/page';
@use '../../base/typography';

main {
    .campuses {
        padding-bottom: measurements.$measure--small4;
        @include include-media.media('>=small') {
            @include page.standard-box();
        }

        @include include-media.media('<small') {
            @include page.default-margin();
        }
    }

    .campuses__content {
        p {
            @include typography.heading-font-features();
            @include typography.font-family('heading');
            @include typography.betatype();
        }
    }

    .campuses__links {
        width: 100%;

        &.campuses--stacked {
            .campuses__links__cards {
                grid-template-columns: repeat(1, 1fr);
            }
        }

        .campuses__links__cards {
            list-style: none;
            margin-left: initial;
            margin-bottom: initial;
            max-width: inherit;

            @include include-media.media('>=tablet') {
                display: grid;
                grid-template-columns: repeat(3, 1fr);
                grid-column-gap: measurements.$measure--small2;
                grid-row-gap: measurements.$measure--small2;
            }

            li {
                margin-top: initial;

                @include include-media.media('<=between') {
                    margin-bottom: measurements.$measure--basic;
                    max-width: initial;
                }

                .campuses__links__anchor {
                    outline-offset: measurements.$measure--quarter;
                    display: block;
                    border-bottom: 0;

                    @include include-media.media('<=between') {
                        max-width: initial;
                    }

                    &:hover,
                    &:focus {
                        .campuses__links__card--image:after {
                            opacity: 0;
                            transition: opacity variables.$transition-duration
                                ease-in;
                        }
                    }
                }
            }

            li:nth-child(1) {
                .campuses__links__card--label__heading-icon {
                    background: palette.$color-brand-primary;
                }
            }
            li:nth-child(2) {
                .campuses__links__card--label__heading-icon {
                    background: colors.$color-orange50;
                }
            }
            li:nth-child(3) {
                .campuses__links__card--label__heading-icon {
                    background: colors.$color-teal60;
                }
            }
        }

        .campuses__links__card {
            position: relative;
        }

        .campuses__links__card--image {
            line-height: 0;

            &::after {
                content: '';
                position: absolute;
                left: 0;
                top: 0;
                height: 100%;
                width: 100%;
                background-image: linear-gradient(
                    0deg,
                    rgba(0, 0, 0, 0.5),
                    transparent
                );
                opacity: 1;
                transition: opacity variables.$transition-duration ease-in;
            }
        }

        figure {
            margin-top: 0;
        }

        .campuses__links__card--label {
            position: absolute;
            background-color: colors.$color-purewhite;
            color: colors.$color-nearblack;
            bottom: measurements.$measure--small1;
            left: measurements.$measure--small1;

            .campuses__links__card--label__heading {
                display: inline-flex;
                margin-bottom: initial;
                text-wrap: wrap;
                margin-top: 0;
            }

            .campuses__links__card--label__heading-text {
                padding: measurements.$measure--half;
                @include typography.betatype();
            }

            .campuses__links__card--label__heading-icon {
                color: colors.$color-purewhite;
                padding: measurements.$measure--half
                    measurements.$measure--basic;
                line-height: 0;
                display: flex;
                flex-direction: column;
                justify-content: center;
                align-items: center;
            }
        }
    }
}
