@use '../../../abstracts/media' as include-media;
@use '../../../abstracts/colors';
@use '../../../abstracts/functions';
@use '../../../abstracts/measurements';
@use '../../../abstracts/variables';
@use '../../../base/typography';

@mixin filterBrightness() {
    -webkit-filter: brightness(0.2);
    filter: brightness(0.2);
}

@mixin transitionBrightness() {
    -moz-transition: filter 0.5s cubic-bezier(0.165, 0.84, 0.44, 1);
    -webkit-transition: filter 0.5s cubic-bezier(0.165, 0.84, 0.44, 1);
    transition: filter 0.5s cubic-bezier(0.165, 0.84, 0.44, 1);
}

@mixin toolTipHyperLink() {
    display: inline;
    color: colors.$color-purewhite;
    text-decoration: underline;
    text-decoration-thickness: variables.$border-width-hairline;
    text-underline-offset: variables.$border-width-thick;
    transition: text-decoration-thickness variables.$transition-duration
        variables.$transition-function;

    &:visited {
        color: colors.$color-purewhite;
    }

    &:hover,
    &:active {
        text-decoration-thickness: variables.$border-width-default;
    }

    &:focus {
        text-decoration-thickness: variables.$border-width-default;
        outline-color: colors.$color-red50;
    }

    &:before {
        background: initial;
        opacity: initial;
        width: initial;
        height: initial;
    }
}

.wrapper--tooltip__label {
    @include include-media.media('>=mobile', '<tablet') {
        display: none;
    }
    @include typography.smalltype();

    margin-top: initial;
    position: absolute;
    right: 0;
    top: 0;
    z-index: functions.z-index('above');
    width: 100%;

    &[data-open='false'] {
        .tooltip__label {
            display: none;
        }
    }

    .tooltip__label {
        display: inline-block;
        margin-left: measurements.$measure--basic;
        color: colors.$color-purewhite;
        padding: 0 measurements.$measure--half;
        border-left: variables.$border-style-solid variables.$border-width-thick
            colors.$color-purewhite;
        @include typography.extrasmalltype();

        a {
            @include toolTipHyperLink;
        }
    }

    .tooltip--image-credit {
        @include typography.smalltype();
        background-color: colors.$color-gray10;
        border: 0;
        color: colors.$color-purewhite;
        font-weight: variables.$font-weight-normal;
        margin: 0;
        padding: measurements.$measure--half;
        width: auto;
        pointer-events: auto;
        &:hover {
            @include include-media.media('hover') {
                background-color: colors.$color-red50;
            }
        }

        &:focus {
            background-color: colors.$color-red50;
        }

        &:active,
        &:focus {
            outline: 0;

            .icon {
                outline: variables.$border-width-default
                    variables.$border-style-solid colors.$color-purewhite;
            }
        }

        .icon {
            min-width: measurements.$measure--small3;
            padding: measurements.$measure--quarter;
            font-size: typography.$font-size--alpha;
        }
    }
}

.tooltip__overlay {
    @include transitionBrightness();
}

img:has(~ .wrapper--tooltip__label[data-open='true']) {
    @include filterBrightness();
}

.card--news {
    .wrapper--tooltip__label ~ .card__anchor img {
        @include transitionBrightness();
    }

    .wrapper--tooltip__label[data-open='true'] ~ .card__anchor img {
        @include filterBrightness();
    }
}

.card--pathway {
    .wrapper--tooltip__label ~ a img {
        @include transitionBrightness();
    }
    .wrapper--tooltip__label[data-open='true'] ~ a img {
        @include filterBrightness();
    }
}

.news__related-news {
    .card--news {
        .wrapper--tooltip__label {
            margin: variables.$border-width-thick;
            width: calc(
                100% - #{variables.$border-width-thick} - #{variables.$border-width-thick}
            );
        }
    }
}

.finder__results {
    .card--news {
        .wrapper--tooltip__label {
            margin: variables.$border-width-thicker;
            width: calc(
                100% - #{variables.$border-width-thicker} - #{variables.$border-width-thicker}
            );
        }
    }
}

.pathway {
    .pathway__cards {
        .card--pathway {
            position: relative;
            .wrapper--tooltip__label {
                margin: initial;

                a {
                    border-left: initial;
                    border-right: initial;
                    border-top: initial;
                    background-color: initial;
                    @include toolTipHyperLink;

                    &:active,
                    &:hover,
                    &:focus {
                        background-color: initial;
                    }
                }
            }

            a {
                @include include-media.media('hover') {
                    &:hover {
                        .card--pathway__content {
                            background-color: colors.$color-gray1;
                        }
                    }
                }
            }
        }
    }
}

[class*='whats-happening'],
.content-hub [class*='happening'] {
    .wrapper--tooltip__label {
        right: initial;
        top: 3.4rem;
    }
}
