@use 'sass:string';
@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../anchors/navigation';
@use '../../anchors/outline';
@use '../../anchors/reset';
@use '../../base/content';
@use '../../base/page';
@use '../../base/typography';
@use '../../fontawesome-7/sharp-regular';
@use '../../fontawesome-7/variables' as fa-variables;
@use '../../fontawesome-7/mixins' as fa-mixins;

.navigation--primary {
    @include include-media.media('<desktop') {
        padding-top: measurements.$measure--small1;
        border-top: variables.$border-width-hairline
            variables.$border-style-solid colors.$color-gray2;
    }

    ul {
        list-style: none;
        margin-left: 0;
        margin-top: 0;
        max-width: unset;
    }

    .navigation__level1 {
        @include content.h5style();

        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        justify-content: space-between;
        list-style: none;
        margin-top: 0;

        @include include-media.media('>=desktop') {
            justify-content: flex-end;
        }

        > li {
            margin-right: measurements.$measure--small2;

            > a {
                min-height: variables.$minimum-control-height;
            }

            &:last-of-type {
                margin-right: 0;
            }
        }
    }

    /*
     * Primary navigation curation.
     */
    .navigation--primary__level1 {
        &[data-title='Prospective students'],
        &[data-title='About us'] {
            .navigation__level2 {
                grid-template-rows: repeat(9, auto);

                > li:first-of-type {
                    grid-row: 1 / span 9;
                    justify-content: flex-start;
                }
            }
        }

        &[data-title='Research'],
        &[data-title='For businesses'],
        &[data-title='Alumni and supporters'] {
            .navigation__level2 {
                grid-template-rows: repeat(4, auto);

                > li:first-of-type {
                    grid-row: 1 / span 4;
                    justify-content: flex-start;
                }
            }
        }

        &[data-title='News and events'] {
            .navigation__level2 {
                grid-template-rows: repeat(2, auto);

                > li:first-of-type {
                    grid-row: 1 / 1;
                    justify-content: flex-start;
                }
            }
        }
    }

    .navigation__level2 {
        column-gap: measurements.$measure--small2;
        display: grid;
        grid-auto-flow: column;
        grid-template-columns: repeat(2, 1fr);
        grid-template-rows: repeat(4, auto);
        row-gap: measurements.$measure--half;

        > li {
            @include content.h5style();

            margin-top: 0;

            &:not(:first-of-type) {
                a {
                    align-items: center;
                    display: flex;
                    height: 100%;
                }
            }

            > a,
            > .navigation__current > span {
                &:after {
                    @include typography.font-family('sharp');

                    content: '\f054';
                    font-size: typography.$font-size--icon;
                    font-weight: variables.$font-weight-light;
                    margin-left: measurements.$measure--half;
                }
            }
        }

        a {
            @include navigation.navigation-anchor(
                $color: colors.$color-purewhite,
                $background: colors.$color-gray10,
                $hover-color: colors.$color-purewhite,
                $hover-background: colors.$color-gray8,
                $outline: colors.$color-purewhite
            );
        }

        a,
        .navigation__current > span {
            display: block;
            padding-bottom: measurements.$measure--half;
            padding-left: measurements.$measure--half;
            padding-right: measurements.$measure--half;
            padding-top: measurements.$measure--half;
            width: 100%;

            & > span {
                display: inline;
            }
        }

        .navigation__hierarchy > a > span {
            border-bottom-color: colors.$color-purewhite;
            border-bottom-style: variables.$border-style-solid;
            border-bottom-width: variables.$border-width-default;
        }

        .navigation__current > a {
            align-items: center;

            > span {
                border-bottom-color: colors.$color-red50;
                border-bottom-style: variables.$border-style-solid;
                border-bottom-width: variables.$border-width-default;
            }
        }
    }

    .navigation__level2 > li:first-of-type {
        grid-row: 1 / span 4;

        > .navigation__level3 {
            display: block;
        }
    }

    .navigation__level3 > li {
        @include content.content-style();
        @include typography.smalltype();

        margin-top: 0;
    }

    .navigation__level3 {
        display: none;

        a,
        .navigation__current > span {
            padding-left: measurements.$measure--half;
        }
    }

    .navigation__level1,
    .navigation__level2,
    .navigation__level3 {
        max-width: unset;
    }

    .navigation--primary__menu {
        background-color: colors.$color-gray10;
        color: colors.$color-purewhite;
        left: 0;
        position: absolute;
        width: 100%;
        z-index: functions.z-index(navigation);
        transform-origin: top;
        animation-duration: 0s;
        animation-timing-function: linear;
        animation-fill-mode: forwards;
        overflow-y: hidden;
    }

    .navigation--primary__menu__content {
        @include page.standard-box();

        column-gap: measurements.$measure--small2;
        display: grid;
        grid-template-columns: 1fr 2fr;
        grid-template-rows: repeat(2, auto);
        padding-bottom: measurements.$measure--basic;
        padding-left: measurements.$measure--basic;
        padding-right: measurements.$measure--basic;
        padding-top: measurements.$measure--basic;

        .navigation__current {
            display: flex;
            flex-direction: column;
            justify-content: center;
        }
    }

    .wrapper--navigation--primary__menu__close {
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        grid-column-end: span 4;
        grid-column-start: 1;
        grid-row-end: 1;
        grid-row-start: 1;
        justify-content: flex-end;

        button {
            @include navigation.navigation-button(
                colors.$color-purewhite,
                colors.$color-gray10,
                colors.$color-gray8,
                colors.$color-purewhite
            );
            @include content.h5style();

            margin-top: 0;
            padding: measurements.$measure--quarter;
        }
    }

    .navigation--primary__menu__close__text {
        @include mixins.sr-only();
    }

    .navigation--primary__menu__header {
        @include content.h4style();

        margin-top: 0;

        a,
        > span {
            display: block;
            padding-bottom: measurements.$measure--half;
            padding-left: measurements.$measure--half;
            padding-right: measurements.$measure--half;
            padding-top: measurements.$measure--half;

            > span {
                display: inline;
            }
        }

        a {
            @include navigation.navigation-anchor(
                $color: colors.$color-purewhite,
                $background: colors.$color-gray10,
                $hover-color: colors.$color-purewhite,
                $hover-background: colors.$color-gray8,
                $outline: colors.$color-purewhite
            );
        }

        a,
        > span {
            &:after {
                @include typography.font-family('sharp');

                content: '\f054';
                font-size: typography.$font-size--icon;
                font-weight: variables.$font-weight-light;
                margin-left: measurements.$measure--half;
            }
        }
    }

    .navigation__hierarchy {
        .navigation--primary__menu__header {
            span {
                border-bottom-color: colors.$color-purewhite;
                border-bottom-style: variables.$border-style-solid;
                border-bottom-width: variables.$border-width-default;
            }
        }
    }

    .navigation__current {
        .navigation--primary__menu__header {
            span {
                border-bottom-color: colors.$color-red50;
                border-bottom-style: variables.$border-style-solid;
                border-bottom-width: variables.$border-width-default;
            }
        }
    }

    .navigation--primary__menu {
        visibility: hidden;
    }

    .navigation--primary__level1 {
        & > button div,
        & > a {
            border-bottom-width: variables.$border-width-default;
            border-bottom-style: variables.$border-style-solid;
            border-bottom-color: transparent;
        }

        &.navigation__hierarchy {
            & > button div,
            & > a {
                border-bottom-color: colors.$color-nearblack;
            }
        }

        &.navigation__current {
            & > button div,
            & > a {
                border-bottom-color: colors.$color-red50;
            }
        }
    }
}

@mixin open-menu-properties() {
    & > div:after {
        color: colors.$color-gray10;
    }

    & + .navigation--primary__menu {
        box-shadow: 0 measurements.$measure--half measurements.$measure--small1
            0 rgba(0, 0, 0, 0.3);
        display: block;
    }
}

.js {
    .navigation--primary {
        .navigation__level1 {
            > li {
                .navigation__button {
                    @include reset.anchor-reset();
                    @include outline.anchor-default-outline(
                        colors.$color-nearblack
                    );

                    position: relative;
                    align-items: center;

                    &:hover {
                        @include include-media.media('hover') {
                            color: colors.$color-red50;

                            div {
                                border-bottom-color: colors.$color-red50;
                            }
                        }
                    }

                    & > div:after {
                        @include typography.font-family('sharp');

                        color: transparent;
                        content: '\f0d8';
                        display: none;
                        font-size: measurements.$measure--small4;
                        font-weight: variables.$font-weight-black;
                        left: 0;
                        position: absolute;
                        width: 100%;
                        margin-top: measurements.$measure--quarter;
                    }

                    & + .navigation--primary__menu {
                        margin-top: measurements.$measure--small2;
                        padding-bottom: measurements.$measure--small2;
                    }

                    &[aria-expanded='false'] {
                        &.menu-animation__slideClose
                            + .navigation--primary__menu {
                            @include mixins.menu-animation-slideClose;
                        }
                    }

                    &[aria-expanded='true'] {
                        & > div:after {
                            display: block;
                            color: colors.$color-gray10;
                        }
                        &.menu-animation__slideOpen
                            + .navigation--primary__menu {
                            box-shadow: 0 measurements.$measure--half
                                measurements.$measure--small1 0
                                rgba(0, 0, 0, 0.3);
                            visibility: visible;
                            @include mixins.menu-animation-slideOpen;
                        }
                    }
                }
            }
        }
    }

    .navigation__veil {
        @include mixins.veil();

        &[data-on='true'] {
            @include include-media.media('<small') {
                display: none;
            }
        }
    }

    .navigation__button__navigation,
    .navigation__button__open-close {
        @include mixins.sr-only();
    }
}

// menu top level chevrons
.navigation--primary {
    .navigation--primary__level1 .navigation__button {
        .navigation--primary__section-text {
            @include include-media.media('<large') {
                @include typography.alphatype();
            }
        }

        &:first-child {
            display: flex;
            &:after {
                @include fa-mixins.fa-icon(Font Awesome 7 Sharp);
                @extend .#{fa-variables.$css-prefix}-solid;
                @extend .#{fa-variables.$css-prefix}-sharp;

                content: string.unquote(
                    '"#{ fa-variables.$var-chevron-down }"'
                );

                display: inline-flex;
                color: colors.$color-red50;
                @include typography.extrasmalltype();
                margin-left: measurements.$measure--half;
                align-items: center;
            }
        }
    }
}

.no-js .navigation--primary {
    .navigation__level1 {
        > li {
            &:hover,
            &:focus-within {
                & > .navigation--primary__menu {
                    box-shadow: 0 measurements.$measure--half
                        measurements.$measure--small1 0 rgba(0, 0, 0, 0.3);
                    display: grid;
                    visibility: visible;
                }
            }
        }
    }
}
