@use 'sass:color';
@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';

////
/// Cookiebot style override
/// @group patterns
////

body > #CybotCookiebotDialog {
    font-family: 'Plex Sans', Tahoma, Verdana;

    #CybotCookiebotDialogBodyLevelButtonLevelOptinAllowallSelectionWrapper {
        .CybotCookiebotDialogBodyButton {
            padding-top: measurements.$measure--half;
            padding-bottom: measurements.$measure--half;
        }
    }

    #CybotCookiebotDialogBodyLevelButtonLevelOptinDeclineAll,
    #CybotCookiebotDialogBodyLevelButtonLevelOptinAllowallSelection {
        border: 1px solid transparent;
        color: colors.$color-red50;
        background-color: transparent;
        transition: border variables.$transition-duration--medium;

        &:hover {
            @include include-media.media('hover') {
                border: 1px solid colors.$color-red50;
            }
        }

        &:focus,
        &:active {
            border: 1px solid colors.$color-red50;
        }
    }

    #CybotCookiebotDialogBodyLevelButtonLevelOptinAllowAll {
        background-color: colors.$color-red50;
        transition: background-color variables.$transition-duration--medium;
        border: 2px dotted transparent;

        &:hover {
            @include include-media.media('hover') {
                background-color: color.adjust(
                    colors.$color-red50,
                    $lightness: -10%
                );
                border: 2px dotted transparent;
            }
        }

        &:focus,
        &:active {
            border: 2px dotted colors.$color-purewhite;
        }
    }
}

/* Branding on the banner */
a#CybotCookiebotDialogPoweredbyCybot,
div#CybotCookiebotDialogPoweredByText {
    display: none;
}
